  ('monopoly', 'Monopoly', '🎩', 'Compra media ciudad y arruina a los demás', null, '{"primary":"#1f7a4d"}'::jsonb, 2, 8, 'Patrimonio', '€', 'explicit', 'highest', null, 0, '{"slug":"monopoly","name":"Monopoly","icon":"🎩","tagline":"Compra media ciudad y arruina a los demás","theme":{"primary":"#1f7a4d"},"minPlayers":2,"maxPlayers":8,"playTime":{"min":90,"max":180},"difficulty":"easy","scoreLabel":"Patrimonio","scoreLabelShort":"€","totalMode":"explicit","winnerRule":"highest","fields":[{"key":"net_worth","label":"Patrimonio final","short":"Patrimonio","icon":"💰","type":"number","points":1,"isTotal":true,"showInSummary":true,"hint":"Dinero + precio de tus solares + casas y hoteles"},{"key":"properties","label":"Solares","icon":"🏘️","type":"counter","group":"Registro","min":0,"max":28,"hint":"No suma: se guarda como estadística"},{"key":"houses","label":"Casas","icon":"🏠","type":"counter","group":"Registro","min":0,"max":32},{"key":"hotels","label":"Hoteles","icon":"🏨","type":"counter","group":"Registro","min":0,"max":12},{"key":"bankrupt","label":"Quebró","icon":"💸","type":"toggle","group":"Registro","hint":"Marca a quien se quedó sin nada antes de acabar"}],"tools":[{"kind":"dice","count":2,"faces":6}],"rules":{"players":"2–8 jugadores","duration":"90–180 min","setup":["Cada jugador coge una ficha y 1.500 € repartidos en billetes de todos los valores.","Baraja las cartas de Suerte y Caja de Comunidad y déjalas boca abajo en su casilla.","Las escrituras, casas y hoteles se quedan en el banco, ordenadas y a la vista.","Elegid banquero: lleva el dinero del banco aparte del suyo.","Todas las fichas empiezan en la casilla de Salida.","Empieza quien saque el número más alto con los dos dados."],"turn":[{"name":"1. Tirar y mover","detail":"Avanza la suma de los dos dados. Si sacas dobles, repites turno; a los terceros dobles seguidos vas directo a la cárcel."},{"name":"2. Resolver la casilla","detail":"Si el solar no tiene dueño, lo compras al precio de la escritura o sale a subasta. Si es de otro, le pagas el alquiler (solo si te lo reclama antes de la siguiente tirada)."},{"name":"3. Negociar y construir","detail":"Puedes intercambiar solares y dinero con quien quieras, hipotecar, deshipotecar y construir casas si tienes un color completo."}],"scoring":[{"what":"Solar suelto","points":"Alquiler base"},{"what":"Color completo sin construir","points":"Alquiler ×2"},{"what":"Casas (1 a 4)","points":"Alquiler creciente"},{"what":"Hotel","points":"Alquiler máximo"},{"what":"Estación","points":"25 € × estaciones que tengas"},{"what":"Compañía","points":"4 × dados (10 × si tienes las dos)"},{"what":"Pasar por Salida","points":"+200 €"}],"endCondition":"Gana el último que queda sin quebrar. Si jugáis con límite de tiempo, gana quien tenga más patrimonio: dinero + precio de compra de sus solares + coste de sus casas y hoteles (los hipotecados valen la mitad).","reminders":["Si no compras un solar libre, sale a subasta obligatoriamente y puede quedárselo cualquiera, incluso por 1 €.","Para construir necesitas TODO el color y hay que edificar de forma uniforme: no puedes poner la segunda casa hasta que todos los solares del color tengan una.","Un solar hipotecado no cobra alquiler, y el color completo tampoco dobla si uno de sus solares está hipotecado.","El dinero de las multas no se acumula en el Parking Gratuito: eso es una regla de la casa, no del reglamento.","En la cárcel sigues cobrando alquileres y puedes negociar con normalidad."],"officialLink":{"label":"Web oficial (Hasbro)","url":"https://www.hasbro.com/en-us/brands/monopoly"}}}'::jsonb, null, 90, 180, 'easy', '{"players":"2–8 jugadores","duration":"90–180 min","setup":["Cada jugador coge una ficha y 1.500 € repartidos en billetes de todos los valores.","Baraja las cartas de Suerte y Caja de Comunidad y déjalas boca abajo en su casilla.","Las escrituras, casas y hoteles se quedan en el banco, ordenadas y a la vista.","Elegid banquero: lleva el dinero del banco aparte del suyo.","Todas las fichas empiezan en la casilla de Salida.","Empieza quien saque el número más alto con los dos dados."],"turn":[{"name":"1. Tirar y mover","detail":"Avanza la suma de los dos dados. Si sacas dobles, repites turno; a los terceros dobles seguidos vas directo a la cárcel."},{"name":"2. Resolver la casilla","detail":"Si el solar no tiene dueño, lo compras al precio de la escritura o sale a subasta. Si es de otro, le pagas el alquiler (solo si te lo reclama antes de la siguiente tirada)."},{"name":"3. Negociar y construir","detail":"Puedes intercambiar solares y dinero con quien quieras, hipotecar, deshipotecar y construir casas si tienes un color completo."}],"scoring":[{"what":"Solar suelto","points":"Alquiler base"},{"what":"Color completo sin construir","points":"Alquiler ×2"},{"what":"Casas (1 a 4)","points":"Alquiler creciente"},{"what":"Hotel","points":"Alquiler máximo"},{"what":"Estación","points":"25 € × estaciones que tengas"},{"what":"Compañía","points":"4 × dados (10 × si tienes las dos)"},{"what":"Pasar por Salida","points":"+200 €"}],"endCondition":"Gana el último que queda sin quebrar. Si jugáis con límite de tiempo, gana quien tenga más patrimonio: dinero + precio de compra de sus solares + coste de sus casas y hoteles (los hipotecados valen la mitad).","reminders":["Si no compras un solar libre, sale a subasta obligatoriamente y puede quedárselo cualquiera, incluso por 1 €.","Para construir necesitas TODO el color y hay que edificar de forma uniforme: no puedes poner la segunda casa hasta que todos los solares del color tengan una.","Un solar hipotecado no cobra alquiler, y el color completo tampoco dobla si uno de sus solares está hipotecado.","El dinero de las multas no se acumula en el Parking Gratuito: eso es una regla de la casa, no del reglamento.","En la cárcel sigues cobrando alquileres y puedes negociar con normalidad."],"officialLink":{"label":"Web oficial (Hasbro)","url":"https://www.hasbro.com/en-us/brands/monopoly"}}'::jsonb, 1406, null, 0, null, null, 'monopoly compra media ciudad y arruina a los demas'),
  ('trivial-pursuit', 'Trivial Pursuit', '🧀', 'Seis quesitos y la pregunta final', null, '{"primary":"#7a3fb3"}'::jsonb, 2, 6, 'Quesitos', 'Q', 'computed', 'highest', 7, 1, '{"slug":"trivial-pursuit","name":"Trivial Pursuit","icon":"🧀","tagline":"Seis quesitos y la pregunta final","theme":{"primary":"#7a3fb3"},"minPlayers":2,"maxPlayers":6,"playTime":{"min":60,"max":90},"difficulty":"easy","scoreLabel":"Quesitos","scoreLabelShort":"Q","totalMode":"computed","winnerRule":"highest","targetScore":7,"fields":[{"key":"wedges","label":"Quesitos conseguidos","short":"Quesitos","icon":"🧀","type":"counter","points":1,"min":0,"max":6,"showInSummary":true,"hint":"Uno por cada categoría"},{"key":"center","label":"Acertó la pregunta final","short":"Final","icon":"🎯","type":"toggle","points":1,"uniquePerMatch":true,"showInSummary":true,"hint":"Solo lo consigue quien gana la partida"},{"key":"right_answers","label":"Respuestas acertadas","short":"Aciertos","icon":"✅","type":"counter","group":"Registro","min":0,"max":99,"hint":"No suma: se guarda como estadística"}],"tools":[{"kind":"dice","count":1,"faces":6}],"rules":{"players":"2–6 jugadores o equipos","duration":"60–90 min","setup":["Cada jugador coge un queso vacío y lo pone en la casilla central.","Coloca las cajas de cartas al alcance de todos, con las respuestas tapadas.","Repartid quién lee cada carta: siempre la lee el jugador de la izquierda.","Decidid antes de empezar si jugáis por parejas o cada uno por su cuenta.","Empieza quien saque el número más alto con el dado."],"turn":[{"name":"1. Tirar y elegir camino","detail":"Avanza las casillas del dado en la dirección que quieras, pero sin cambiar de sentido a mitad de movimiento."},{"name":"2. Responder","detail":"Te preguntan de la categoría del color de tu casilla. Si aciertas, vuelves a tirar; si fallas, pasa el turno al siguiente."},{"name":"3. Casillas de quesito","detail":"Si caes en una de las seis casillas grandes y aciertas, te llevas el quesito de ese color. Si ya lo tenías, simplemente repites tirada."}],"scoring":[{"what":"Acertar en una casilla normal","points":"Repites tirada"},{"what":"Acertar en casilla de quesito","points":"1 quesito"},{"what":"Caer en «Tira otra vez»","points":"Turno extra"},{"what":"Los seis quesitos","points":"Puedes ir al centro"},{"what":"Pregunta final acertada","points":"Ganas la partida"}],"endCondition":"Cuando tienes los seis quesitos vas al centro con la tirada exacta. Allí los demás eligen la categoría de la pregunta final: si aciertas ganas, y si fallas te sales del centro y esperas a tu siguiente turno para volver a intentarlo.","reminders":["La respuesta se da antes de que se lea la solución: no vale rectificar después de oírla.","Para entrar en el centro hay que sacar el número exacto.","No puedes cambiar de dirección a mitad de un movimiento, aunque sí de una tirada a otra.","Si juegas por parejas, solo responde quien tiene el turno; el compañero no puede soplar."],"officialLink":{"label":"Web oficial (Hasbro)","url":"https://www.hasbro.com/en-us/brands/trivialpursuit"}}}'::jsonb, null, 60, 90, 'easy', '{"players":"2–6 jugadores o equipos","duration":"60–90 min","setup":["Cada jugador coge un queso vacío y lo pone en la casilla central.","Coloca las cajas de cartas al alcance de todos, con las respuestas tapadas.","Repartid quién lee cada carta: siempre la lee el jugador de la izquierda.","Decidid antes de empezar si jugáis por parejas o cada uno por su cuenta.","Empieza quien saque el número más alto con el dado."],"turn":[{"name":"1. Tirar y elegir camino","detail":"Avanza las casillas del dado en la dirección que quieras, pero sin cambiar de sentido a mitad de movimiento."},{"name":"2. Responder","detail":"Te preguntan de la categoría del color de tu casilla. Si aciertas, vuelves a tirar; si fallas, pasa el turno al siguiente."},{"name":"3. Casillas de quesito","detail":"Si caes en una de las seis casillas grandes y aciertas, te llevas el quesito de ese color. Si ya lo tenías, simplemente repites tirada."}],"scoring":[{"what":"Acertar en una casilla normal","points":"Repites tirada"},{"what":"Acertar en casilla de quesito","points":"1 quesito"},{"what":"Caer en «Tira otra vez»","points":"Turno extra"},{"what":"Los seis quesitos","points":"Puedes ir al centro"},{"what":"Pregunta final acertada","points":"Ganas la partida"}],"endCondition":"Cuando tienes los seis quesitos vas al centro con la tirada exacta. Allí los demás eligen la categoría de la pregunta final: si aciertas ganas, y si fallas te sales del centro y esperas a tu siguiente turno para volver a intentarlo.","reminders":["La respuesta se da antes de que se lea la solución: no vale rectificar después de oírla.","Para entrar en el centro hay que sacar el número exacto.","No puedes cambiar de dirección a mitad de un movimiento, aunque sí de una tirada a otra.","Si juegas por parejas, solo responde quien tiene el turno; el compañero no puede soplar."],"officialLink":{"label":"Web oficial (Hasbro)","url":"https://www.hasbro.com/en-us/brands/trivialpursuit"}}'::jsonb, 2952, null, 0, null, null, 'trivial pursuit seis quesitos y la pregunta final'),
  ('scrabble', 'Scrabble', '🔤', 'Palabras cruzadas por puntos', null, '{"primary":"#8a6a3d"}'::jsonb, 2, 4, 'Puntos', 'Pts', 'explicit', 'highest', null, 2, '{"slug":"scrabble","name":"Scrabble","icon":"🔤","tagline":"Palabras cruzadas por puntos","theme":{"primary":"#8a6a3d"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":45,"max":90},"difficulty":"medium","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","fields":[{"key":"points","label":"Puntos finales","short":"Puntos","icon":"🔤","type":"number","points":1,"isTotal":true,"showInSummary":true,"hint":"Ya con el ajuste de las fichas que quedaban en el atril"},{"key":"bingos","label":"Palabras de siete fichas","short":"Scrabbles","icon":"💥","type":"counter","group":"Registro","min":0,"max":20,"hint":"Cada una da +50 puntos, ya incluidos arriba"},{"key":"best_word","label":"Mejor jugada","short":"Mejor","icon":"⭐","type":"number","group":"Registro","min":0,"hint":"Puntos de la palabra más cara que colocaste"}],"tools":[{"kind":"timer","seconds":120,"label":"Reloj de turno"}],"rules":{"players":"2–4 jugadores","duration":"45–90 min","setup":["Mete las 100 fichas en la bolsa y mézclalas.","Cada jugador saca una ficha: empieza quien tenga la letra más cercana a la A (el comodín gana a todo).","Devolved esas fichas a la bolsa y cada uno se pone siete en su atril.","Poned a mano un diccionario acordado de antemano: es el que resuelve las dudas.","La primera palabra tiene que pasar por la casilla central."],"turn":[{"name":"1. Colocar","detail":"Forma una palabra en horizontal o vertical (nunca en diagonal ni al revés) que enlace con alguna ficha ya puesta."},{"name":"2. Contar","detail":"Suma el valor de todas las palabras nuevas que hayas formado, incluidas las que se crean de refilón al pegar tu palabra a otra."},{"name":"3. Reponer","detail":"Coge de la bolsa hasta volver a tener siete fichas. En lugar de jugar puedes cambiar fichas o pasar, pero pierdes el turno."}],"scoring":[{"what":"Letra","points":"Su valor impreso"},{"what":"Casilla de letra doble o triple","points":"×2 / ×3 a esa letra"},{"what":"Casilla de palabra doble o triple","points":"×2 / ×3 a la palabra entera"},{"what":"Primera palabra (casilla central)","points":"Palabra ×2"},{"what":"Usar las siete fichas","points":"+50 puntos"},{"what":"Fichas que te sobran al final","points":"−su valor"},{"what":"Si alguien se queda sin fichas","points":"+ lo que sobre a los demás"}],"endCondition":"La partida acaba cuando alguien coloca su última ficha y la bolsa está vacía, o cuando todos pasan dos veces seguidas. Cada jugador resta el valor de las fichas que le sobran; quien se quedó sin ninguna suma todo eso a su marcador.","reminders":["Las casillas de bonificación solo cuentan el turno en que se cubren; después son casillas normales.","El comodín vale 0 puntos siempre, aunque esté en una casilla de letra triple.","La bonificación de letra se aplica antes que la de palabra.","Si una jugada forma varias palabras, se puntúan todas, y las casillas de bonificación cuentan en cada una.","Nada de nombres propios, abreviaturas ni palabras con guion o apóstrofo."],"officialLink":{"label":"Web oficial (Hasbro)","url":"https://scrabble.hasbro.com/en-us"}}}'::jsonb, null, 45, 90, 'medium', '{"players":"2–4 jugadores","duration":"45–90 min","setup":["Mete las 100 fichas en la bolsa y mézclalas.","Cada jugador saca una ficha: empieza quien tenga la letra más cercana a la A (el comodín gana a todo).","Devolved esas fichas a la bolsa y cada uno se pone siete en su atril.","Poned a mano un diccionario acordado de antemano: es el que resuelve las dudas.","La primera palabra tiene que pasar por la casilla central."],"turn":[{"name":"1. Colocar","detail":"Forma una palabra en horizontal o vertical (nunca en diagonal ni al revés) que enlace con alguna ficha ya puesta."},{"name":"2. Contar","detail":"Suma el valor de todas las palabras nuevas que hayas formado, incluidas las que se crean de refilón al pegar tu palabra a otra."},{"name":"3. Reponer","detail":"Coge de la bolsa hasta volver a tener siete fichas. En lugar de jugar puedes cambiar fichas o pasar, pero pierdes el turno."}],"scoring":[{"what":"Letra","points":"Su valor impreso"},{"what":"Casilla de letra doble o triple","points":"×2 / ×3 a esa letra"},{"what":"Casilla de palabra doble o triple","points":"×2 / ×3 a la palabra entera"},{"what":"Primera palabra (casilla central)","points":"Palabra ×2"},{"what":"Usar las siete fichas","points":"+50 puntos"},{"what":"Fichas que te sobran al final","points":"−su valor"},{"what":"Si alguien se queda sin fichas","points":"+ lo que sobre a los demás"}],"endCondition":"La partida acaba cuando alguien coloca su última ficha y la bolsa está vacía, o cuando todos pasan dos veces seguidas. Cada jugador resta el valor de las fichas que le sobran; quien se quedó sin ninguna suma todo eso a su marcador.","reminders":["Las casillas de bonificación solo cuentan el turno en que se cubren; después son casillas normales.","El comodín vale 0 puntos siempre, aunque esté en una casilla de letra triple.","La bonificación de letra se aplica antes que la de palabra.","Si una jugada forma varias palabras, se puntúan todas, y las casillas de bonificación cuentan en cada una.","Nada de nombres propios, abreviaturas ni palabras con guion o apóstrofo."],"officialLink":{"label":"Web oficial (Hasbro)","url":"https://scrabble.hasbro.com/en-us"}}'::jsonb, 320, null, 0, null, null, 'scrabble palabras cruzadas por puntos'),
  ('uno', 'UNO', '🃏', 'Quédate sin cartas y grita a tiempo', null, '{"primary":"#d62828"}'::jsonb, 2, 10, 'Puntos', 'Pts', 'explicit', 'highest', 500, 3, '{"slug":"uno","name":"UNO","icon":"🃏","tagline":"Quédate sin cartas y grita a tiempo","theme":{"primary":"#d62828"},"minPlayers":2,"maxPlayers":10,"playTime":{"min":30,"max":45},"difficulty":"easy","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","targetScore":500,"fields":[{"key":"points","label":"Puntos acumulados","short":"Puntos","icon":"🏆","type":"number","points":1,"isTotal":true,"showInSummary":true,"hint":"Se juega hasta que alguien llega a 500"},{"key":"rounds_won","label":"Rondas ganadas","short":"Rondas","icon":"✋","type":"counter","group":"Registro","min":0,"max":50,"showInSummary":true},{"key":"forgot_uno","label":"Se le olvidó decir UNO","short":"¡UNO!","icon":"🤫","type":"counter","group":"Registro","min":0,"max":50,"hint":"Cada despiste son 2 cartas de penalización"}],"rules":{"players":"2–10 jugadores","duration":"30–45 min","setup":["Baraja las 108 cartas y reparte siete a cada jugador.","El resto forma el mazo de robo, boca abajo.","Dale la vuelta a la primera carta: empieza el descarte.","Si la carta de salida es un +4, devuélvela al mazo y saca otra.","Empieza el jugador de la izquierda de quien reparte."],"turn":[{"name":"1. Tirar o robar","detail":"Juega una carta que coincida con el color, el número o el símbolo de la de arriba, o cualquier comodín. Si no puedes o no quieres, robas una carta."},{"name":"2. La carta robada","detail":"Si la carta que acabas de robar se puede jugar, puedes echarla en ese mismo turno; si no, pasas."},{"name":"3. Cantar UNO","detail":"Al quedarte con una sola carta tienes que decir «¡UNO!» antes de que te pillen. Si otro jugador te caza, robas dos cartas."}],"scoring":[{"what":"Cartas numeradas (0–9)","points":"Su número"},{"what":"+2, Cambio de sentido, Salta","points":"20 puntos"},{"what":"Comodín y comodín +4","points":"50 puntos"},{"what":"Ganador de la ronda","points":"Suma lo que quede en las manos ajenas"},{"what":"Meta de la partida","points":"500 puntos"}],"endCondition":"La ronda acaba cuando alguien se queda sin cartas: suma el valor de todas las cartas que les quedan a los demás. Gana la partida quien llegue primero a 500 puntos.","reminders":["Solo se acumulan +2 sobre +2 si lo habéis acordado antes: no está en el reglamento oficial.","El comodín +4 solo se puede jugar si no tienes ninguna carta del color en curso; el siguiente jugador puede desafiarte y mirar tu mano.","Con dos jugadores, el Cambio de sentido funciona igual que un Salta.","Si se acaba el mazo de robo, se baraja el descarte —menos la carta de arriba— y se sigue.","Solo puedes cantar UNO cuando de verdad te queda una carta; hacerlo antes no vale."],"officialLink":{"label":"Web oficial (Mattel)","url":"https://www.mattelgames.com/en-us/cards/uno"}}}'::jsonb, null, 30, 45, 'easy', '{"players":"2–10 jugadores","duration":"30–45 min","setup":["Baraja las 108 cartas y reparte siete a cada jugador.","El resto forma el mazo de robo, boca abajo.","Dale la vuelta a la primera carta: empieza el descarte.","Si la carta de salida es un +4, devuélvela al mazo y saca otra.","Empieza el jugador de la izquierda de quien reparte."],"turn":[{"name":"1. Tirar o robar","detail":"Juega una carta que coincida con el color, el número o el símbolo de la de arriba, o cualquier comodín. Si no puedes o no quieres, robas una carta."},{"name":"2. La carta robada","detail":"Si la carta que acabas de robar se puede jugar, puedes echarla en ese mismo turno; si no, pasas."},{"name":"3. Cantar UNO","detail":"Al quedarte con una sola carta tienes que decir «¡UNO!» antes de que te pillen. Si otro jugador te caza, robas dos cartas."}],"scoring":[{"what":"Cartas numeradas (0–9)","points":"Su número"},{"what":"+2, Cambio de sentido, Salta","points":"20 puntos"},{"what":"Comodín y comodín +4","points":"50 puntos"},{"what":"Ganador de la ronda","points":"Suma lo que quede en las manos ajenas"},{"what":"Meta de la partida","points":"500 puntos"}],"endCondition":"La ronda acaba cuando alguien se queda sin cartas: suma el valor de todas las cartas que les quedan a los demás. Gana la partida quien llegue primero a 500 puntos.","reminders":["Solo se acumulan +2 sobre +2 si lo habéis acordado antes: no está en el reglamento oficial.","El comodín +4 solo se puede jugar si no tienes ninguna carta del color en curso; el siguiente jugador puede desafiarte y mirar tu mano.","Con dos jugadores, el Cambio de sentido funciona igual que un Salta.","Si se acaba el mazo de robo, se baraja el descarte —menos la carta de arriba— y se sigue.","Solo puedes cantar UNO cuando de verdad te queda una carta; hacerlo antes no vale."],"officialLink":{"label":"Web oficial (Mattel)","url":"https://www.mattelgames.com/en-us/cards/uno"}}'::jsonb, 2223, null, 0, null, null, 'uno quedate sin cartas y grita a tiempo'),
  ('rummikub', 'Rummikub', '🎴', 'Grupos, escaleras y fichas que cambian de sitio', null, '{"primary":"#1d6fa5"}'::jsonb, 2, 4, 'Puntos', 'Pts', 'explicit', 'highest', null, 4, '{"slug":"rummikub","name":"Rummikub","icon":"🎴","tagline":"Grupos, escaleras y fichas que cambian de sitio","theme":{"primary":"#1d6fa5"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":45,"max":60},"difficulty":"easy","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","fields":[{"key":"points","label":"Puntos acumulados","short":"Puntos","icon":"🏆","type":"number","points":1,"isTotal":true,"showInSummary":true,"hint":"Suele quedar en negativo salvo para quien gana rondas"},{"key":"rounds_won","label":"Rondas ganadas","short":"Rondas","icon":"🥇","type":"counter","group":"Registro","min":0,"max":30,"showInSummary":true},{"key":"jokers_left","label":"Comodines que se le quedaron","short":"Comodines","icon":"🃏","type":"counter","group":"Registro","min":0,"max":4,"hint":"Cada uno son 30 puntos en contra"}],"tools":[{"kind":"timer","seconds":60,"label":"Reloj de turno"}],"rules":{"players":"2–4 jugadores","duration":"45–60 min","setup":["Pon las 106 fichas boca abajo sobre la mesa y mézclalas.","Cada jugador coge 14 fichas y las coloca en su atril sin enseñarlas.","El resto de fichas se queda en el centro como reserva.","Empieza quien saque la ficha más alta en el sorteo inicial."],"turn":[{"name":"1. Salir","detail":"Tu primera jugada tiene que sumar al menos 30 puntos usando solo fichas de tu atril. Hasta que sales no puedes tocar lo que hay en la mesa."},{"name":"2. Jugar y reorganizar","detail":"Una vez has salido puedes añadir fichas a cualquier combinación y descomponer y rehacer lo que hay en la mesa, siempre que al acabar tu turno todo sean grupos o escaleras válidos."},{"name":"3. Robar","detail":"Si no colocas ninguna ficha, coges una de la reserva y pasa el turno. Tienes un minuto para pensar si jugáis con reloj."}],"scoring":[{"what":"Cada ficha","points":"Su número"},{"what":"Comodín en la mesa","points":"El valor de la ficha que sustituye"},{"what":"Salida mínima","points":"30 puntos en una sola jugada"},{"what":"Fichas que te sobran","points":"−su valor"},{"what":"Comodín sin usar","points":"−30 puntos"},{"what":"Ganador de la ronda","points":"+ la suma de lo que pierden los demás"}],"endCondition":"La ronda acaba cuando alguien se queda sin fichas (o cuando nadie puede jugar y la reserva está vacía: gana quien menos puntos tenga en el atril). Cada jugador resta el valor de sus fichas y el ganador suma en positivo todo lo que restan los demás. La partida son varias rondas: gana quien acabe con más puntos.","reminders":["Un grupo son 3 o 4 fichas del mismo número y distinto color; una escalera son 3 o más números seguidos del mismo color.","El 1 va siempre por debajo del 2: no enlaza con el 13 para hacer 12-13-1.","La salida de 30 puntos se cuenta solo con tus fichas; no vale apoyarse en la mesa.","Si al acabar tu turno queda una combinación inválida, deshaces la jugada y robas tres fichas de penalización.","Un comodín que ya está en la mesa solo se puede recuperar sustituyéndolo por la ficha exacta que representa, y hay que usarlo en ese mismo turno."],"officialLink":{"label":"Web oficial (Rummikub)","url":"https://www.rummikub.com/"}}}'::jsonb, null, 45, 60, 'easy', '{"players":"2–4 jugadores","duration":"45–60 min","setup":["Pon las 106 fichas boca abajo sobre la mesa y mézclalas.","Cada jugador coge 14 fichas y las coloca en su atril sin enseñarlas.","El resto de fichas se queda en el centro como reserva.","Empieza quien saque la ficha más alta en el sorteo inicial."],"turn":[{"name":"1. Salir","detail":"Tu primera jugada tiene que sumar al menos 30 puntos usando solo fichas de tu atril. Hasta que sales no puedes tocar lo que hay en la mesa."},{"name":"2. Jugar y reorganizar","detail":"Una vez has salido puedes añadir fichas a cualquier combinación y descomponer y rehacer lo que hay en la mesa, siempre que al acabar tu turno todo sean grupos o escaleras válidos."},{"name":"3. Robar","detail":"Si no colocas ninguna ficha, coges una de la reserva y pasa el turno. Tienes un minuto para pensar si jugáis con reloj."}],"scoring":[{"what":"Cada ficha","points":"Su número"},{"what":"Comodín en la mesa","points":"El valor de la ficha que sustituye"},{"what":"Salida mínima","points":"30 puntos en una sola jugada"},{"what":"Fichas que te sobran","points":"−su valor"},{"what":"Comodín sin usar","points":"−30 puntos"},{"what":"Ganador de la ronda","points":"+ la suma de lo que pierden los demás"}],"endCondition":"La ronda acaba cuando alguien se queda sin fichas (o cuando nadie puede jugar y la reserva está vacía: gana quien menos puntos tenga en el atril). Cada jugador resta el valor de sus fichas y el ganador suma en positivo todo lo que restan los demás. La partida son varias rondas: gana quien acabe con más puntos.","reminders":["Un grupo son 3 o 4 fichas del mismo número y distinto color; una escalera son 3 o más números seguidos del mismo color.","El 1 va siempre por debajo del 2: no enlaza con el 13 para hacer 12-13-1.","La salida de 30 puntos se cuenta solo con tus fichas; no vale apoyarse en la mesa.","Si al acabar tu turno queda una combinación inválida, deshaces la jugada y robas tres fichas de penalización.","Un comodín que ya está en la mesa solo se puede recuperar sustituyéndolo por la ficha exacta que representa, y hay que usarlo en ese mismo turno."],"officialLink":{"label":"Web oficial (Rummikub)","url":"https://www.rummikub.com/"}}'::jsonb, 811, null, 0, null, null, 'rummikub grupos escaleras y fichas que cambian de sitio'),
  ('domino', 'Dominó', '🁫', 'Cierra la mano y cuenta los puntos ajenos', null, '{"primary":"#2f2f38"}'::jsonb, 2, 4, 'Puntos', 'Pts', 'explicit', 'highest', 100, 5, '{"slug":"domino","name":"Dominó","icon":"🁫","tagline":"Cierra la mano y cuenta los puntos ajenos","theme":{"primary":"#2f2f38"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":30,"max":60},"difficulty":"easy","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","targetScore":100,"fields":[{"key":"points","label":"Puntos acumulados","short":"Puntos","icon":"🏆","type":"number","points":1,"isTotal":true,"min":0,"showInSummary":true,"hint":"Se juega a 100 puntos (o a lo que acordéis)"},{"key":"rounds_won","label":"Manos ganadas","short":"Manos","icon":"🁣","type":"counter","group":"Registro","min":0,"max":40,"showInSummary":true},{"key":"capicua","label":"Cierres con capicúa","short":"Capicúas","icon":"✨","type":"counter","group":"Registro","min":0,"max":20,"hint":"Cerrar con una ficha que vale por los dos extremos"}],"rules":{"players":"2–4 jugadores (lo habitual, dos parejas)","duration":"30–60 min","setup":["Pon las 28 fichas boca abajo y revuélvelas bien.","Con cuatro jugadores cada uno coge 7 fichas; con dos, 7 cada uno y el resto queda como reserva.","Si jugáis por parejas, los compañeros se sientan enfrentados.","La primera mano la abre quien tenga el doble seis; en las siguientes, quien ganó la anterior."],"turn":[{"name":"1. Colocar","detail":"Encadena una ficha por cualquiera de los dos extremos abiertos, haciendo coincidir los números."},{"name":"2. Pasar","detail":"Si no tienes ninguna ficha que encaje, pasas (o robas de la reserva si jugáis con ella). Se juega en el sentido de las agujas del reloj."},{"name":"3. Cierre","detail":"La mano termina en cuanto alguien coloca su última ficha, o cuando la partida se tranca porque nadie puede jugar."}],"scoring":[{"what":"Ganar la mano","points":"Suma los puntos de las fichas ajenas"},{"what":"Partida trancada","points":"Gana quien menos puntos tenga en la mano"},{"what":"Cada ficha en la mano rival","points":"Su total de puntos"},{"what":"Meta de la partida","points":"100 puntos"}],"endCondition":"Se juegan tantas manos como haga falta hasta que un jugador o una pareja llega a 100 puntos. Si la mano se tranca, cuenta los puntos quien tenga menos fichas en la mano; en parejas se suma lo de los dos compañeros.","reminders":["Solo se puede colocar por los dos extremos de la fila: los dobles se ponen atravesados pero no abren camino nuevo.","Si puedes jugar, estás obligado a hacerlo: no vale pasar por estrategia.","En parejas está prohibido dar pistas, señas o comentar lo que llevas.","Si la partida se tranca en empate a puntos, la mano se anula o la gana quien la abrió, según lo que acordéis antes de empezar."]}}'::jsonb, null, 30, 60, 'easy', '{"players":"2–4 jugadores (lo habitual, dos parejas)","duration":"30–60 min","setup":["Pon las 28 fichas boca abajo y revuélvelas bien.","Con cuatro jugadores cada uno coge 7 fichas; con dos, 7 cada uno y el resto queda como reserva.","Si jugáis por parejas, los compañeros se sientan enfrentados.","La primera mano la abre quien tenga el doble seis; en las siguientes, quien ganó la anterior."],"turn":[{"name":"1. Colocar","detail":"Encadena una ficha por cualquiera de los dos extremos abiertos, haciendo coincidir los números."},{"name":"2. Pasar","detail":"Si no tienes ninguna ficha que encaje, pasas (o robas de la reserva si jugáis con ella). Se juega en el sentido de las agujas del reloj."},{"name":"3. Cierre","detail":"La mano termina en cuanto alguien coloca su última ficha, o cuando la partida se tranca porque nadie puede jugar."}],"scoring":[{"what":"Ganar la mano","points":"Suma los puntos de las fichas ajenas"},{"what":"Partida trancada","points":"Gana quien menos puntos tenga en la mano"},{"what":"Cada ficha en la mano rival","points":"Su total de puntos"},{"what":"Meta de la partida","points":"100 puntos"}],"endCondition":"Se juegan tantas manos como haga falta hasta que un jugador o una pareja llega a 100 puntos. Si la mano se tranca, cuenta los puntos quien tenga menos fichas en la mano; en parejas se suma lo de los dos compañeros.","reminders":["Solo se puede colocar por los dos extremos de la fila: los dobles se ponen atravesados pero no abren camino nuevo.","Si puedes jugar, estás obligado a hacerlo: no vale pasar por estrategia.","En parejas está prohibido dar pistas, señas o comentar lo que llevas.","Si la partida se tranca en empate a puntos, la mano se anula o la gana quien la abrió, según lo que acordéis antes de empezar."]}'::jsonb, null, null, 0, null, null, 'domino cierra la mano y cuenta los puntos ajenos'),
  ('parchis', 'Parchís', '🎲', 'Veinte de contar y comer', null, '{"primary":"#c62828"}'::jsonb, 2, 4, 'Fichas en casa', 'Casa', 'computed', 'highest', 4, 6, '{"slug":"parchis","name":"Parchís","icon":"🎲","tagline":"Veinte de contar y comer","theme":{"primary":"#c62828"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":30,"max":60},"difficulty":"easy","scoreLabel":"Fichas en casa","scoreLabelShort":"Casa","totalMode":"computed","winnerRule":"highest","targetScore":4,"fields":[{"key":"home","label":"Fichas que llegaron a casa","short":"En casa","icon":"🏁","type":"counter","points":1,"min":0,"max":4,"showInSummary":true},{"key":"eaten","label":"Fichas que se comió","short":"Comidas","icon":"😋","type":"counter","group":"Registro","min":0,"max":20,"showInSummary":true,"hint":"No suma: se guarda como estadística"},{"key":"was_eaten","label":"Veces que se lo comieron","short":"Comido","icon":"💀","type":"counter","group":"Registro","min":0,"max":20}],"tools":[{"kind":"dice","count":1,"faces":6}],"rules":{"players":"2–4 jugadores","duration":"30–60 min","setup":["Cada jugador elige un color y pone sus cuatro fichas en su casilla de salida.","Colocad el tablero de forma que cada uno tenga su color delante.","Empieza quien saque el 5 más rápido, o sortead el orden con el dado.","Se juega en el sentido de las agujas del reloj."],"turn":[{"name":"1. Tirar el dado","detail":"Mueve una ficha tantas casillas como marque el dado. Necesitas un 5 para sacar una ficha de la salida."},{"name":"2. Comer","detail":"Si acabas el movimiento en una casilla ocupada por una sola ficha rival —y no es un seguro—, se la comes: vuelve a su salida y tú avanzas 20 casillas."},{"name":"3. Repetir","detail":"Sacar un 6 te da otra tirada; a los tres seises seguidos, la ficha que movías vuelve a la salida. Comer da 20 y meter una ficha en casa da 10, y ambos se cuentan aparte del dado."}],"scoring":[{"what":"Sacar ficha de la salida","points":"Un 5 en el dado"},{"what":"Comer una ficha","points":"Avanzas 20"},{"what":"Meter una ficha en casa","points":"Avanzas 10"},{"what":"Sacar un 6","points":"Tiras otra vez"},{"what":"Tres seises seguidos","points":"La ficha vuelve a la salida"},{"what":"Meta de la partida","points":"Las 4 fichas en casa"}],"endCondition":"Gana quien mete sus cuatro fichas en la casilla central. Si queréis clasificar a todos, seguid jugando hasta que el resto también llegue, o apuntad cuántas fichas tenía cada uno en casa al terminar.","reminders":["Dos fichas en la misma casilla forman barrera y nadie puede pasar por encima, ni siquiera tú.","En las casillas de seguro (las grises y las de salida) no se puede comer.","Para entrar en el pasillo final y en la casa hace falta el número exacto; si te pasas, el movimiento no vale.","Si tienes fichas en la salida y sacas un 5, estás obligado a sacar una.","Con solo una ficha fuera, el 6 se mueve como 7 en la variante más extendida: acordadlo antes de empezar."]}}'::jsonb, null, 30, 60, 'easy', '{"players":"2–4 jugadores","duration":"30–60 min","setup":["Cada jugador elige un color y pone sus cuatro fichas en su casilla de salida.","Colocad el tablero de forma que cada uno tenga su color delante.","Empieza quien saque el 5 más rápido, o sortead el orden con el dado.","Se juega en el sentido de las agujas del reloj."],"turn":[{"name":"1. Tirar el dado","detail":"Mueve una ficha tantas casillas como marque el dado. Necesitas un 5 para sacar una ficha de la salida."},{"name":"2. Comer","detail":"Si acabas el movimiento en una casilla ocupada por una sola ficha rival —y no es un seguro—, se la comes: vuelve a su salida y tú avanzas 20 casillas."},{"name":"3. Repetir","detail":"Sacar un 6 te da otra tirada; a los tres seises seguidos, la ficha que movías vuelve a la salida. Comer da 20 y meter una ficha en casa da 10, y ambos se cuentan aparte del dado."}],"scoring":[{"what":"Sacar ficha de la salida","points":"Un 5 en el dado"},{"what":"Comer una ficha","points":"Avanzas 20"},{"what":"Meter una ficha en casa","points":"Avanzas 10"},{"what":"Sacar un 6","points":"Tiras otra vez"},{"what":"Tres seises seguidos","points":"La ficha vuelve a la salida"},{"what":"Meta de la partida","points":"Las 4 fichas en casa"}],"endCondition":"Gana quien mete sus cuatro fichas en la casilla central. Si queréis clasificar a todos, seguid jugando hasta que el resto también llegue, o apuntad cuántas fichas tenía cada uno en casa al terminar.","reminders":["Dos fichas en la misma casilla forman barrera y nadie puede pasar por encima, ni siquiera tú.","En las casillas de seguro (las grises y las de salida) no se puede comer.","Para entrar en el pasillo final y en la casa hace falta el número exacto; si te pasas, el movimiento no vale.","Si tienes fichas en la salida y sacas un 5, estás obligado a sacar una.","Con solo una ficha fuera, el 6 se mueve como 7 en la variante más extendida: acordadlo antes de empezar."]}'::jsonb, 2136, null, 0, null, null, 'parchis veinte de contar y comer'),
  ('catan', 'Catán', '🌾', 'Coloniza la isla y llega a 10 puntos de victoria', null, '{"primary":"#b5582a"}'::jsonb, 3, 6, 'Puntos de victoria', 'PV', 'computed', 'highest', 10, 7, '{"slug":"catan","name":"Catán","icon":"🌾","tagline":"Coloniza la isla y llega a 10 puntos de victoria","theme":{"primary":"#b5582a"},"minPlayers":3,"maxPlayers":6,"playTime":{"min":60,"max":90},"difficulty":"medium","scoreLabel":"Puntos de victoria","scoreLabelShort":"PV","totalMode":"computed","winnerRule":"highest","targetScore":10,"fields":[{"key":"settlements","label":"Pueblos","icon":"🏠","type":"counter","points":1,"group":"Construcciones","min":0,"max":5,"showInSummary":true,"hint":"1 PV cada uno"},{"key":"cities","label":"Ciudades","icon":"🏙️","type":"counter","points":2,"group":"Construcciones","min":0,"max":4,"showInSummary":true,"hint":"2 PV cada una"},{"key":"dev_points","label":"Puntos de cartas de desarrollo","short":"Cartas PV","icon":"🃏","type":"counter","points":1,"group":"Cartas","min":0,"max":5,"hint":"1 PV cada carta de punto de victoria"},{"key":"longest_road","label":"Camino más largo","icon":"🛤️","type":"toggle","points":2,"group":"Cartas","uniquePerMatch":true,"showInSummary":true,"hint":"+2 PV · 5 tramos continuos mínimo"},{"key":"largest_army","label":"Ejército más grande","icon":"⚔️","type":"toggle","points":2,"group":"Cartas","uniquePerMatch":true,"showInSummary":true,"hint":"+2 PV · 3 caballeros mínimo"},{"key":"knights","label":"Caballeros jugados","short":"Caballeros","icon":"🛡️","type":"counter","group":"Registro","min":0,"max":14,"hint":"No suma PV, se guarda como estadística"},{"key":"roads","label":"Carreteras","icon":"🛣️","type":"counter","group":"Registro","min":0,"max":15,"hint":"No suma PV, se guarda como estadística"}],"tools":[{"kind":"dice","count":2,"faces":6,"label":"Dados de producción"}],"rules":{"players":"3–4 jugadores (hasta 6 con la ampliación)","duration":"60–90 min","setup":["Monta los 19 hexágonos al azar dentro del marco de mar.","Reparte las fichas de número en espiral desde una esquina; el desierto se queda sin número.","Coloca el ladrón en el desierto.","Cada jugador coge sus 5 pueblos, 4 ciudades y 15 carreteras.","Por orden de turno cada uno coloca 1 pueblo + 1 carretera; después, en orden inverso, el segundo pueblo + carretera.","Recibes una materia por cada hexágono que toque tu segundo pueblo."],"turn":[{"name":"1. Tirar los dados","detail":"Producen todos los hexágonos con ese número: 1 materia por pueblo adyacente, 2 por ciudad. Produce todo el mundo, no solo quien tira."},{"name":"2. Si sale un 7","detail":"Quien tenga más de 7 cartas descarta la mitad (redondeando hacia abajo). Mueves el ladrón a otro hexágono y robas una carta al azar a un jugador que tenga construcción allí. El hexágono con el ladrón deja de producir."},{"name":"3. Comerciar","detail":"Con los demás jugadores en los términos que queráis, o con la banca 4:1 (3:1 o 2:1 si tienes el puerto correspondiente)."},{"name":"4. Construir","detail":"Tantas construcciones como puedas pagar, en cualquier orden. También puedes comprar cartas de desarrollo."}],"scoring":[{"what":"Carretera · 🌲 + 🧱","points":"0 PV"},{"what":"Pueblo · 🌲 + 🧱 + 🌾 + 🐑","points":"1 PV"},{"what":"Ciudad (sustituye a un pueblo) · 2🌾 + 3⛰️","points":"2 PV"},{"what":"Carta de desarrollo · 🌾 + 🐑 + ⛰️","points":"0 o 1 PV"},{"what":"Camino más largo · 5+ tramos continuos","points":"2 PV"},{"what":"Ejército más grande · 3+ caballeros jugados","points":"2 PV"}],"endCondition":"Gana quien llegue a 10 puntos de victoria durante su propio turno. Las cartas de PV ocultas se revelan justo en ese momento.","reminders":["Regla de la distancia: entre dos pueblos debe haber siempre al menos un cruce libre.","Solo puedes construir conectando con tu propia red de carreteras.","Una carta de desarrollo por turno, y nunca la que acabas de comprar (las de PV no se juegan, cuentan siempre).","El ladrón tiene que moverse a un hexágono distinto del que ocupaba.","El camino más largo y el ejército más grande cambian de dueño si otro te supera; empatar no basta."],"officialLink":{"label":"Reglamento oficial (Catan GmbH)","url":"https://www.catan.com/understand-catan/game-rules"}}}'::jsonb, null, 60, 90, 'medium', '{"players":"3–4 jugadores (hasta 6 con la ampliación)","duration":"60–90 min","setup":["Monta los 19 hexágonos al azar dentro del marco de mar.","Reparte las fichas de número en espiral desde una esquina; el desierto se queda sin número.","Coloca el ladrón en el desierto.","Cada jugador coge sus 5 pueblos, 4 ciudades y 15 carreteras.","Por orden de turno cada uno coloca 1 pueblo + 1 carretera; después, en orden inverso, el segundo pueblo + carretera.","Recibes una materia por cada hexágono que toque tu segundo pueblo."],"turn":[{"name":"1. Tirar los dados","detail":"Producen todos los hexágonos con ese número: 1 materia por pueblo adyacente, 2 por ciudad. Produce todo el mundo, no solo quien tira."},{"name":"2. Si sale un 7","detail":"Quien tenga más de 7 cartas descarta la mitad (redondeando hacia abajo). Mueves el ladrón a otro hexágono y robas una carta al azar a un jugador que tenga construcción allí. El hexágono con el ladrón deja de producir."},{"name":"3. Comerciar","detail":"Con los demás jugadores en los términos que queráis, o con la banca 4:1 (3:1 o 2:1 si tienes el puerto correspondiente)."},{"name":"4. Construir","detail":"Tantas construcciones como puedas pagar, en cualquier orden. También puedes comprar cartas de desarrollo."}],"scoring":[{"what":"Carretera · 🌲 + 🧱","points":"0 PV"},{"what":"Pueblo · 🌲 + 🧱 + 🌾 + 🐑","points":"1 PV"},{"what":"Ciudad (sustituye a un pueblo) · 2🌾 + 3⛰️","points":"2 PV"},{"what":"Carta de desarrollo · 🌾 + 🐑 + ⛰️","points":"0 o 1 PV"},{"what":"Camino más largo · 5+ tramos continuos","points":"2 PV"},{"what":"Ejército más grande · 3+ caballeros jugados","points":"2 PV"}],"endCondition":"Gana quien llegue a 10 puntos de victoria durante su propio turno. Las cartas de PV ocultas se revelan justo en ese momento.","reminders":["Regla de la distancia: entre dos pueblos debe haber siempre al menos un cruce libre.","Solo puedes construir conectando con tu propia red de carreteras.","Una carta de desarrollo por turno, y nunca la que acabas de comprar (las de PV no se juegan, cuentan siempre).","El ladrón tiene que moverse a un hexágono distinto del que ocupaba.","El camino más largo y el ejército más grande cambian de dueño si otro te supera; empatar no basta."],"officialLink":{"label":"Reglamento oficial (Catan GmbH)","url":"https://www.catan.com/understand-catan/game-rules"}}'::jsonb, 13, null, 0, null, null, 'catan coloniza la isla y llega a 10 puntos de victoria'),
  ('carcassonne', 'Carcassonne', '🏰', 'Coloca losetas, reclama ciudades y caminos', null, '{"primary":"#4a6fa5"}'::jsonb, 2, 5, 'Puntos', 'Pts', 'explicit', 'highest', null, 8, '{"slug":"carcassonne","name":"Carcassonne","icon":"🏰","tagline":"Coloca losetas, reclama ciudades y caminos","theme":{"primary":"#4a6fa5"},"minPlayers":2,"maxPlayers":5,"playTime":{"min":30,"max":45},"difficulty":"medium","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","fields":[{"key":"points","label":"Puntos","icon":"🎯","type":"number","isTotal":true,"min":0,"max":400,"showInSummary":true,"hint":"Marcador final del jugador"},{"key":"cities","label":"Ciudades","icon":"🏰","type":"number","group":"Desglose (opcional)","min":0,"max":400},{"key":"roads","label":"Caminos","icon":"🛣️","type":"number","group":"Desglose (opcional)","min":0,"max":400},{"key":"monasteries","label":"Monasterios","icon":"⛪","type":"number","group":"Desglose (opcional)","min":0,"max":400},{"key":"farms","label":"Campos","icon":"🌾","type":"number","group":"Desglose (opcional)","min":0,"max":400}],"rules":{"players":"2–5 jugadores","duration":"30–45 min","setup":["Coloca la loseta inicial (la del dorso más oscuro) en el centro de la mesa.","Baraja el resto de losetas y déjalas boca abajo en montones.","Cada jugador coge sus 8 seguidores: 7 en la reserva y 1 en el marcador de puntos, en la casilla 0."],"turn":[{"name":"1. Robar y colocar loseta","detail":"Roba una loseta y colócala junto a otra ya jugada. Todos los lados en contacto deben encajar: campo con campo, camino con camino, ciudad con ciudad."},{"name":"2. Colocar seguidor (opcional)","detail":"Pon un seguidor de tu reserva sobre la loseta que acabas de colocar: en la ciudad (caballero), el camino (ladrón), el monasterio (monje) o el campo (granjero). Solo si ese elemento no tiene ya un seguidor de nadie."},{"name":"3. Puntuar lo completado","detail":"Todo elemento que quede terminado con esa loseta puntúa de inmediato y sus seguidores vuelven a la reserva de sus dueños."}],"scoring":[{"what":"Camino terminado (cerrado por ambos extremos)","points":"1 por loseta"},{"what":"Ciudad terminada (muralla cerrada)","points":"2 por loseta + 2 por escudo"},{"what":"Monasterio rodeado por las 8 losetas","points":"9"},{"what":"Final · camino sin terminar","points":"1 por loseta"},{"what":"Final · ciudad sin terminar","points":"1 por loseta + 1 por escudo"},{"what":"Final · monasterio sin rodear","points":"1 por su loseta + 1 por vecina"},{"what":"Final · campo (granjero)","points":"3 por ciudad terminada que toque"}],"endCondition":"La partida acaba cuando se coloca la última loseta. Entonces se puntúan todos los elementos sin terminar y los campos. Gana quien tenga más puntos.","reminders":["No puedes poner un seguidor en un elemento ya ocupado, pero sí crear uno propio y unirlo después: si al unirse hay empate de seguidores, puntúan todos los empatados.","Los granjeros no vuelven nunca a la reserva: se quedan en el campo hasta el final.","Se puntúa en el mismo momento en que el elemento se completa, no al final.","Si una loseta no encaja en ningún hueco del tablero, se descarta y robas otra.","Un elemento incompleto puntúa mucho menos: cerrar ciudades grandes es lo que decide la partida."],"officialLink":{"label":"Reglamento oficial (Hans im Glück)","url":"https://www.hans-im-glueck.de/carcassonne"}}}'::jsonb, null, 30, 45, 'medium', '{"players":"2–5 jugadores","duration":"30–45 min","setup":["Coloca la loseta inicial (la del dorso más oscuro) en el centro de la mesa.","Baraja el resto de losetas y déjalas boca abajo en montones.","Cada jugador coge sus 8 seguidores: 7 en la reserva y 1 en el marcador de puntos, en la casilla 0."],"turn":[{"name":"1. Robar y colocar loseta","detail":"Roba una loseta y colócala junto a otra ya jugada. Todos los lados en contacto deben encajar: campo con campo, camino con camino, ciudad con ciudad."},{"name":"2. Colocar seguidor (opcional)","detail":"Pon un seguidor de tu reserva sobre la loseta que acabas de colocar: en la ciudad (caballero), el camino (ladrón), el monasterio (monje) o el campo (granjero). Solo si ese elemento no tiene ya un seguidor de nadie."},{"name":"3. Puntuar lo completado","detail":"Todo elemento que quede terminado con esa loseta puntúa de inmediato y sus seguidores vuelven a la reserva de sus dueños."}],"scoring":[{"what":"Camino terminado (cerrado por ambos extremos)","points":"1 por loseta"},{"what":"Ciudad terminada (muralla cerrada)","points":"2 por loseta + 2 por escudo"},{"what":"Monasterio rodeado por las 8 losetas","points":"9"},{"what":"Final · camino sin terminar","points":"1 por loseta"},{"what":"Final · ciudad sin terminar","points":"1 por loseta + 1 por escudo"},{"what":"Final · monasterio sin rodear","points":"1 por su loseta + 1 por vecina"},{"what":"Final · campo (granjero)","points":"3 por ciudad terminada que toque"}],"endCondition":"La partida acaba cuando se coloca la última loseta. Entonces se puntúan todos los elementos sin terminar y los campos. Gana quien tenga más puntos.","reminders":["No puedes poner un seguidor en un elemento ya ocupado, pero sí crear uno propio y unirlo después: si al unirse hay empate de seguidores, puntúan todos los empatados.","Los granjeros no vuelven nunca a la reserva: se quedan en el campo hasta el final.","Se puntúa en el mismo momento en que el elemento se completa, no al final.","Si una loseta no encaja en ningún hueco del tablero, se descarta y robas otra.","Un elemento incompleto puntúa mucho menos: cerrar ciudades grandes es lo que decide la partida."],"officialLink":{"label":"Reglamento oficial (Hans im Glück)","url":"https://www.hans-im-glueck.de/carcassonne"}}'::jsonb, 822, null, 0, null, null, 'carcassonne coloca losetas reclama ciudades y caminos'),
  ('camel-up', 'Camel Up', '🐪', 'Apuesta por camellos que se montan unos encima de otros', null, '{"primary":"#956c1b"}'::jsonb, 3, 8, 'Monedas', '🪙', 'explicit', 'highest', null, 9, '{"slug":"camel-up","name":"Camel Up","icon":"🐪","tagline":"Apuesta por camellos que se montan unos encima de otros","theme":{"primary":"#956c1b"},"minPlayers":3,"maxPlayers":8,"playTime":{"min":20,"max":30},"difficulty":"easy","scoreLabel":"Monedas","scoreLabelShort":"🪙","totalMode":"explicit","winnerRule":"highest","fields":[{"key":"coins","label":"Monedas","icon":"🪙","type":"number","isTotal":true,"min":0,"max":200,"showInSummary":true,"hint":"Monedas al final de la carrera"},{"key":"leg_bets","label":"Apuestas de etapa","icon":"🎫","type":"number","group":"Desglose (opcional)","min":-20,"max":200},{"key":"race_bets","label":"Apuestas de carrera","icon":"🏁","type":"number","group":"Desglose (opcional)","min":-20,"max":200},{"key":"pyramid_tickets","label":"Fichas de pirámide","icon":"🔺","type":"counter","group":"Desglose (opcional)","min":0,"max":60},{"key":"desert_tiles","label":"Casillas de desierto","icon":"🏜️","type":"counter","group":"Desglose (opcional)","min":0,"max":60}],"tools":[{"kind":"dice","count":1,"faces":3,"label":"Dado de la pirámide"}],"rules":{"players":"3–8 jugadores","duration":"20–30 min","setup":["Monta la pirámide de dados y coloca el tablero de la pista.","Tira los 5 dados de camello y coloca cada camello en la casilla 1, 2 o 3 según su resultado. Si caen en la misma casilla, se apilan.","Cada jugador recibe 3 monedas, su loseta de desierto (oasis por una cara, espejismo por la otra) y su abanico de cartas de apuesta de carrera.","Apila las losetas de apuesta de etapa por colores, con el valor 5 arriba."],"turn":[{"name":"Elige UNA de estas 4 acciones","detail":"En tu turno haces una sola acción y pasas al siguiente jugador."},{"name":"A · Sacar un dado de la pirámide","detail":"Mueve ese camello tantas casillas como indique el dado y coges 1 moneda. Los camellos que estén encima viajan con él."},{"name":"B · Apostar por la etapa","detail":"Coge la loseta superior de la pila de un camello. Cuanto antes apuestas, más vale."},{"name":"C · Colocar tu loseta de desierto","detail":"En una casilla vacía que no sea la de salida ni esté pegada a otra loseta de desierto. Oasis (+1) o espejismo (−1)."},{"name":"D · Apostar por el final de la carrera","detail":"Pon una de tus cartas boca abajo en la pila de ganador o en la de perdedor. Solo una carta por camello."}],"scoring":[{"what":"Sacar un dado de la pirámide","points":"+1"},{"what":"Apuesta de etapa · camello 1.º de la etapa","points":"+5 / +3 / +2 según la loseta"},{"what":"Apuesta de etapa · camello 2.º de la etapa","points":"+1"},{"what":"Apuesta de etapa fallada","points":"−1"},{"what":"Otro camello pisa tu loseta de desierto","points":"+1"},{"what":"Apuesta de carrera acertada, por orden de la pila","points":"+8 / +5 / +3 / +2 / +1"},{"what":"Apuesta de carrera fallada","points":"−1 por carta"}],"endCondition":"La etapa acaba cuando se han sacado los 5 dados: se pagan las apuestas de etapa, se devuelven dados y losetas y empieza otra. La carrera acaba en cuanto un camello cruza la línea de meta: entonces se pagan las apuestas de ganador y perdedor. Gana quien tenga más monedas.","reminders":["Un camello arrastra a todos los que lleva encima; los de debajo se quedan.","Va en cabeza el camello que esté más adelantado y, dentro de un montón, el que esté más arriba.","Con un oasis (+1) el camello se coloca ENCIMA del montón; con un espejismo (−1) se coloca DEBAJO.","Tu loseta de desierto no puede estar en la casilla de salida ni junto a otra loseta de desierto.","Las apuestas de etapa se resuelven cada etapa; las de carrera, solo al final.","Nunca bajas de 0 monedas: si tienes que pagar y no puedes, te quedas a 0."],"officialLink":{"label":"Reglamento oficial (Pretzel Games)","url":"https://www.pretzelgames.com/en/camel-up"}}}'::jsonb, null, 20, 30, 'easy', '{"players":"3–8 jugadores","duration":"20–30 min","setup":["Monta la pirámide de dados y coloca el tablero de la pista.","Tira los 5 dados de camello y coloca cada camello en la casilla 1, 2 o 3 según su resultado. Si caen en la misma casilla, se apilan.","Cada jugador recibe 3 monedas, su loseta de desierto (oasis por una cara, espejismo por la otra) y su abanico de cartas de apuesta de carrera.","Apila las losetas de apuesta de etapa por colores, con el valor 5 arriba."],"turn":[{"name":"Elige UNA de estas 4 acciones","detail":"En tu turno haces una sola acción y pasas al siguiente jugador."},{"name":"A · Sacar un dado de la pirámide","detail":"Mueve ese camello tantas casillas como indique el dado y coges 1 moneda. Los camellos que estén encima viajan con él."},{"name":"B · Apostar por la etapa","detail":"Coge la loseta superior de la pila de un camello. Cuanto antes apuestas, más vale."},{"name":"C · Colocar tu loseta de desierto","detail":"En una casilla vacía que no sea la de salida ni esté pegada a otra loseta de desierto. Oasis (+1) o espejismo (−1)."},{"name":"D · Apostar por el final de la carrera","detail":"Pon una de tus cartas boca abajo en la pila de ganador o en la de perdedor. Solo una carta por camello."}],"scoring":[{"what":"Sacar un dado de la pirámide","points":"+1"},{"what":"Apuesta de etapa · camello 1.º de la etapa","points":"+5 / +3 / +2 según la loseta"},{"what":"Apuesta de etapa · camello 2.º de la etapa","points":"+1"},{"what":"Apuesta de etapa fallada","points":"−1"},{"what":"Otro camello pisa tu loseta de desierto","points":"+1"},{"what":"Apuesta de carrera acertada, por orden de la pila","points":"+8 / +5 / +3 / +2 / +1"},{"what":"Apuesta de carrera fallada","points":"−1 por carta"}],"endCondition":"La etapa acaba cuando se han sacado los 5 dados: se pagan las apuestas de etapa, se devuelven dados y losetas y empieza otra. La carrera acaba en cuanto un camello cruza la línea de meta: entonces se pagan las apuestas de ganador y perdedor. Gana quien tenga más monedas.","reminders":["Un camello arrastra a todos los que lleva encima; los de debajo se quedan.","Va en cabeza el camello que esté más adelantado y, dentro de un montón, el que esté más arriba.","Con un oasis (+1) el camello se coloca ENCIMA del montón; con un espejismo (−1) se coloca DEBAJO.","Tu loseta de desierto no puede estar en la casilla de salida ni junto a otra loseta de desierto.","Las apuestas de etapa se resuelven cada etapa; las de carrera, solo al final.","Nunca bajas de 0 monedas: si tienes que pagar y no puedes, te quedas a 0."],"officialLink":{"label":"Reglamento oficial (Pretzel Games)","url":"https://www.pretzelgames.com/en/camel-up"}}'::jsonb, 153938, null, 0, null, null, 'camel up apuesta por camellos que se montan unos encima de otros'),
  ('aventureros-al-tren', 'Aventureros al Tren', '🚂', 'Rutas de tren y billetes que hay que cumplir', null, '{"primary":"#b23a48"}'::jsonb, 2, 5, 'Puntos', 'Pts', 'computed', 'highest', null, 10, '{"slug":"aventureros-al-tren","name":"Aventureros al Tren","icon":"🚂","tagline":"Rutas de tren y billetes que hay que cumplir","theme":{"primary":"#b23a48"},"minPlayers":2,"maxPlayers":5,"playTime":{"min":30,"max":60},"difficulty":"easy","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"computed","winnerRule":"highest","fields":[{"key":"board","label":"Rutas del mapa","short":"Rutas","icon":"🛤️","type":"number","points":1,"min":0,"showInSummary":true,"hint":"Lo que fuiste marcando en el marcador durante la partida"},{"key":"tickets_done","label":"Billetes completados","short":"Billetes","icon":"🎟️","type":"number","points":1,"min":0,"showInSummary":true,"hint":"Suma el valor de los billetes que conseguiste unir"},{"key":"tickets_failed","label":"Billetes fallados","short":"Fallados","icon":"❌","type":"number","points":-1,"min":0,"showInSummary":true,"hint":"Suma su valor en positivo: la app ya lo resta"},{"key":"longest_route","label":"Ruta continua más larga","short":"Ruta larga","icon":"🏅","type":"toggle","points":10,"uniquePerMatch":true,"showInSummary":true},{"key":"stations","label":"Estaciones sin usar","short":"Estaciones","icon":"🚉","type":"counter","group":"Registro","min":0,"max":3,"hint":"Solo en la edición Europa: cada una son 4 puntos, súmalos arriba"}],"rules":{"players":"2–5 jugadores","duration":"30–60 min","setup":["Cada jugador coge sus 45 vagones y el marcador de su color, que empieza en la casilla 0.","Reparte 4 cartas de tren a cada uno y pon cinco boca arriba junto al mazo.","Reparte 3 billetes de destino a cada jugador: hay que quedarse con dos como mínimo.","Baraja el resto de billetes en un mazo aparte.","Empieza el jugador más viajero, o sortead."],"turn":[{"name":"Opción A — Coger cartas","detail":"Coges dos cartas de tren, de las visibles o del mazo. Una locomotora visible cuenta por dos: si la coges, es tu única carta del turno."},{"name":"Opción B — Reclamar una ruta","detail":"Descarta tantas cartas del color de la ruta como casillas tenga, coloca tus vagones y avanza tu marcador según la tabla."},{"name":"Opción C — Robar billetes","detail":"Coges tres billetes nuevos y te quedas al menos uno. Los que no cumplas al final restarán."}],"scoring":[{"what":"Ruta de 1 casilla","points":"1 punto"},{"what":"Ruta de 2 casillas","points":"2 puntos"},{"what":"Ruta de 3 casillas","points":"4 puntos"},{"what":"Ruta de 4 casillas","points":"7 puntos"},{"what":"Ruta de 5 casillas","points":"10 puntos"},{"what":"Ruta de 6 casillas","points":"15 puntos"},{"what":"Billete completado","points":"+ su valor"},{"what":"Billete sin completar","points":"− su valor"},{"what":"Ruta continua más larga","points":"+10 puntos"}],"endCondition":"Cuando a un jugador le quedan 2 vagones o menos al final de su turno, todos juegan un último turno (incluido él) y la partida termina. Entonces se enseñan los billetes: los cumplidos suman y los fallados restan, y se da el bonus de la ruta continua más larga.","reminders":["Las rutas dobles solo se pueden usar las dos con 4 o 5 jugadores; con 2 o 3, en cuanto una está ocupada la otra queda bloqueada.","Los billetes se guardan en secreto hasta el recuento final.","Si en las cartas visibles hay tres locomotoras a la vez, se descartan las cinco y se ponen cinco nuevas.","La ruta continua más larga se mide en casillas encadenadas, y puede pasar dos veces por la misma ciudad pero no repetir ruta.","En caso de empate a puntos gana quien haya completado más billetes de destino."],"officialLink":{"label":"Web oficial (Days of Wonder)","url":"https://www.daysofwonder.com/tickettoride/en/"}}}'::jsonb, null, 30, 60, 'easy', '{"players":"2–5 jugadores","duration":"30–60 min","setup":["Cada jugador coge sus 45 vagones y el marcador de su color, que empieza en la casilla 0.","Reparte 4 cartas de tren a cada uno y pon cinco boca arriba junto al mazo.","Reparte 3 billetes de destino a cada jugador: hay que quedarse con dos como mínimo.","Baraja el resto de billetes en un mazo aparte.","Empieza el jugador más viajero, o sortead."],"turn":[{"name":"Opción A — Coger cartas","detail":"Coges dos cartas de tren, de las visibles o del mazo. Una locomotora visible cuenta por dos: si la coges, es tu única carta del turno."},{"name":"Opción B — Reclamar una ruta","detail":"Descarta tantas cartas del color de la ruta como casillas tenga, coloca tus vagones y avanza tu marcador según la tabla."},{"name":"Opción C — Robar billetes","detail":"Coges tres billetes nuevos y te quedas al menos uno. Los que no cumplas al final restarán."}],"scoring":[{"what":"Ruta de 1 casilla","points":"1 punto"},{"what":"Ruta de 2 casillas","points":"2 puntos"},{"what":"Ruta de 3 casillas","points":"4 puntos"},{"what":"Ruta de 4 casillas","points":"7 puntos"},{"what":"Ruta de 5 casillas","points":"10 puntos"},{"what":"Ruta de 6 casillas","points":"15 puntos"},{"what":"Billete completado","points":"+ su valor"},{"what":"Billete sin completar","points":"− su valor"},{"what":"Ruta continua más larga","points":"+10 puntos"}],"endCondition":"Cuando a un jugador le quedan 2 vagones o menos al final de su turno, todos juegan un último turno (incluido él) y la partida termina. Entonces se enseñan los billetes: los cumplidos suman y los fallados restan, y se da el bonus de la ruta continua más larga.","reminders":["Las rutas dobles solo se pueden usar las dos con 4 o 5 jugadores; con 2 o 3, en cuanto una está ocupada la otra queda bloqueada.","Los billetes se guardan en secreto hasta el recuento final.","Si en las cartas visibles hay tres locomotoras a la vez, se descartan las cinco y se ponen cinco nuevas.","La ruta continua más larga se mide en casillas encadenadas, y puede pasar dos veces por la misma ciudad pero no repetir ruta.","En caso de empate a puntos gana quien haya completado más billetes de destino."],"officialLink":{"label":"Web oficial (Days of Wonder)","url":"https://www.daysofwonder.com/tickettoride/en/"}}'::jsonb, 9209, null, 0, null, null, 'aventureros al tren rutas de tren y billetes que hay que cumplir'),
  ('azul', 'Azul', '🔷', 'Azulejos, filas completas y suelo lleno de penalizaciones', null, '{"primary":"#1f5f8b"}'::jsonb, 2, 4, 'Puntos', 'Pts', 'computed', 'highest', null, 11, '{"slug":"azul","name":"Azul","icon":"🔷","tagline":"Azulejos, filas completas y suelo lleno de penalizaciones","theme":{"primary":"#1f5f8b"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":30,"max":45},"difficulty":"medium","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"computed","winnerRule":"highest","fields":[{"key":"board","label":"Puntos del marcador","short":"Marcador","icon":"🧮","type":"number","points":1,"min":0,"showInSummary":true,"hint":"Lo que llevabas apuntado al acabar la última ronda, ya con las penalizaciones"},{"key":"full_rows","label":"Filas horizontales completas","short":"Filas","icon":"➡️","type":"counter","points":2,"min":0,"max":5,"showInSummary":true},{"key":"full_columns","label":"Columnas completas","short":"Columnas","icon":"⬇️","type":"counter","points":7,"min":0,"max":5,"showInSummary":true},{"key":"full_colours","label":"Colores con los cinco azulejos","short":"Colores","icon":"🎨","type":"counter","points":10,"min":0,"max":5,"showInSummary":true}],"rules":{"players":"2–4 jugadores","duration":"30–45 min","setup":["Cada jugador coge un tablero personal y pone su marcador en el 0.","Mete los 100 azulejos en la bolsa.","Coloca los expositores según el número de jugadores: 5 con dos, 7 con tres y 9 con cuatro.","Llena cada expositor con cuatro azulejos sacados de la bolsa.","Pon la ficha de jugador inicial en el centro de la mesa."],"turn":[{"name":"1. Coger azulejos","detail":"Elige un color de un expositor y llévate TODOS los de ese color; los que sobran caen al centro de la mesa. O coge todos los de un color que ya estén en el centro."},{"name":"2. Colocar en una línea","detail":"Pon los azulejos en una de tus cinco líneas de preparación, siempre de derecha a izquierda. Lo que no quepa cae al suelo."},{"name":"3. Alicatar (fin de ronda)","detail":"Cuando expositores y centro se vacían, cada línea completa mueve un azulejo a la pared y puntúa; el resto de esa línea se descarta."}],"scoring":[{"what":"Azulejo aislado","points":"1 punto"},{"what":"Azulejo en una serie","points":"1 por cada azulejo de su fila y columna contiguas"},{"what":"Suelo (penalización)","points":"−1, −1, −2, −2, −2, −3, −3"},{"what":"Fila horizontal completa","points":"+2 puntos"},{"what":"Columna completa","points":"+7 puntos"},{"what":"Los 5 azulejos de un color","points":"+10 puntos"}],"endCondition":"La partida acaba al terminar la ronda en la que alguien completa una fila horizontal entera de su pared. Se aplican los bonus finales de filas, columnas y colores. Si hay empate, gana quien tenga más filas horizontales completas.","reminders":["Quien coge primero del centro se lleva la ficha de jugador inicial y una penalización de −1.","Las líneas de preparación solo admiten un color, y no puedes empezar una línea con un color que ya esté en esa fila de la pared.","Si coges azulejos que no te caben en ninguna línea válida, van todos al suelo.","El marcador nunca baja de cero por muchas penalizaciones que acumules.","Al puntuar un azulejo se cuentan las series horizontal y vertical de las que forme parte, pero solo si tiene vecinos en esa dirección."],"officialLink":{"label":"Web oficial (Next Move Games)","url":"https://www.nextmovegames.com/"}}}'::jsonb, null, 30, 45, 'medium', '{"players":"2–4 jugadores","duration":"30–45 min","setup":["Cada jugador coge un tablero personal y pone su marcador en el 0.","Mete los 100 azulejos en la bolsa.","Coloca los expositores según el número de jugadores: 5 con dos, 7 con tres y 9 con cuatro.","Llena cada expositor con cuatro azulejos sacados de la bolsa.","Pon la ficha de jugador inicial en el centro de la mesa."],"turn":[{"name":"1. Coger azulejos","detail":"Elige un color de un expositor y llévate TODOS los de ese color; los que sobran caen al centro de la mesa. O coge todos los de un color que ya estén en el centro."},{"name":"2. Colocar en una línea","detail":"Pon los azulejos en una de tus cinco líneas de preparación, siempre de derecha a izquierda. Lo que no quepa cae al suelo."},{"name":"3. Alicatar (fin de ronda)","detail":"Cuando expositores y centro se vacían, cada línea completa mueve un azulejo a la pared y puntúa; el resto de esa línea se descarta."}],"scoring":[{"what":"Azulejo aislado","points":"1 punto"},{"what":"Azulejo en una serie","points":"1 por cada azulejo de su fila y columna contiguas"},{"what":"Suelo (penalización)","points":"−1, −1, −2, −2, −2, −3, −3"},{"what":"Fila horizontal completa","points":"+2 puntos"},{"what":"Columna completa","points":"+7 puntos"},{"what":"Los 5 azulejos de un color","points":"+10 puntos"}],"endCondition":"La partida acaba al terminar la ronda en la que alguien completa una fila horizontal entera de su pared. Se aplican los bonus finales de filas, columnas y colores. Si hay empate, gana quien tenga más filas horizontales completas.","reminders":["Quien coge primero del centro se lleva la ficha de jugador inicial y una penalización de −1.","Las líneas de preparación solo admiten un color, y no puedes empezar una línea con un color que ya esté en esa fila de la pared.","Si coges azulejos que no te caben en ninguna línea válida, van todos al suelo.","El marcador nunca baja de cero por muchas penalizaciones que acumules.","Al puntuar un azulejo se cuentan las series horizontal y vertical de las que forme parte, pero solo si tiene vecinos en esa dirección."],"officialLink":{"label":"Web oficial (Next Move Games)","url":"https://www.nextmovegames.com/"}}'::jsonb, 230802, null, 0, null, null, 'azul azulejos filas completas y suelo lleno de penalizaciones'),
  ('splendor', 'Splendor', '💎', 'Gemas, cartas de descuento y carrera a 15', null, '{"primary":"#4a5aa8"}'::jsonb, 2, 4, 'Prestigio', 'PP', 'explicit', 'highest', 15, 12, '{"slug":"splendor","name":"Splendor","icon":"💎","tagline":"Gemas, cartas de descuento y carrera a 15","theme":{"primary":"#4a5aa8"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":30,"max":30},"difficulty":"easy","scoreLabel":"Prestigio","scoreLabelShort":"PP","totalMode":"explicit","winnerRule":"highest","targetScore":15,"fields":[{"key":"prestige","label":"Puntos de prestigio","short":"Prestigio","icon":"💎","type":"number","points":1,"isTotal":true,"min":0,"showInSummary":true,"hint":"Cartas + nobles. Se gana al llegar a 15"},{"key":"nobles","label":"Nobles conseguidos","short":"Nobles","icon":"👑","type":"counter","group":"Registro","min":0,"max":5,"showInSummary":true,"hint":"Cada uno vale 3 puntos, ya incluidos arriba"},{"key":"cards","label":"Cartas de desarrollo","short":"Cartas","icon":"🃏","type":"counter","group":"Registro","min":0,"max":40}],"rules":{"players":"2–4 jugadores","duration":"30 min","setup":["Ordena las cartas por nivel y pon cuatro descubiertas de cada uno.","Coloca los nobles: uno más que jugadores.","Pon las fichas de gema según el número de jugadores: 4 de cada color con dos, 5 con tres y 7 con cuatro.","Los 5 comodines de oro siempre están disponibles.","Empieza quien haya visitado la joyería más recientemente, o sortead."],"turn":[{"name":"Opción A — Coger gemas","detail":"Tres fichas de colores distintos, o dos del mismo color si en esa pila quedan al menos cuatro."},{"name":"Opción B — Comprar una carta","detail":"Paga su coste con gemas y con los descuentos de las cartas que ya tengas; el oro vale por cualquier color."},{"name":"Opción C — Reservar","detail":"Coges una carta visible (o la de arriba del mazo) y te la guardas boca abajo, más una ficha de oro. Máximo tres reservas."}],"scoring":[{"what":"Carta de nivel 1","points":"0–1 puntos"},{"what":"Carta de nivel 2","points":"1–3 puntos"},{"what":"Carta de nivel 3","points":"3–5 puntos"},{"what":"Noble","points":"3 puntos"},{"what":"Meta de la partida","points":"15 puntos de prestigio"}],"endCondition":"Cuando alguien llega a 15 puntos se termina la ronda para que todos hayan jugado los mismos turnos. Gana quien más prestigio tenga; si hay empate, gana quien haya comprado menos cartas de desarrollo.","reminders":["No puedes acabar tu turno con más de 10 fichas: devuelve las que sobren.","Las cartas compradas dan un descuento permanente de su color, no se gastan.","Los nobles llegan solos y son gratis: en cuanto cumples sus requisitos, se van contigo (solo uno por turno).","El oro solo se consigue reservando cartas.","Si en una pila no quedan cuatro fichas, no puedes coger dos del mismo color."],"officialLink":{"label":"Web oficial (Space Cowboys)","url":"https://www.spacecowboys.fr/"}}}'::jsonb, null, 30, 30, 'easy', '{"players":"2–4 jugadores","duration":"30 min","setup":["Ordena las cartas por nivel y pon cuatro descubiertas de cada uno.","Coloca los nobles: uno más que jugadores.","Pon las fichas de gema según el número de jugadores: 4 de cada color con dos, 5 con tres y 7 con cuatro.","Los 5 comodines de oro siempre están disponibles.","Empieza quien haya visitado la joyería más recientemente, o sortead."],"turn":[{"name":"Opción A — Coger gemas","detail":"Tres fichas de colores distintos, o dos del mismo color si en esa pila quedan al menos cuatro."},{"name":"Opción B — Comprar una carta","detail":"Paga su coste con gemas y con los descuentos de las cartas que ya tengas; el oro vale por cualquier color."},{"name":"Opción C — Reservar","detail":"Coges una carta visible (o la de arriba del mazo) y te la guardas boca abajo, más una ficha de oro. Máximo tres reservas."}],"scoring":[{"what":"Carta de nivel 1","points":"0–1 puntos"},{"what":"Carta de nivel 2","points":"1–3 puntos"},{"what":"Carta de nivel 3","points":"3–5 puntos"},{"what":"Noble","points":"3 puntos"},{"what":"Meta de la partida","points":"15 puntos de prestigio"}],"endCondition":"Cuando alguien llega a 15 puntos se termina la ronda para que todos hayan jugado los mismos turnos. Gana quien más prestigio tenga; si hay empate, gana quien haya comprado menos cartas de desarrollo.","reminders":["No puedes acabar tu turno con más de 10 fichas: devuelve las que sobren.","Las cartas compradas dan un descuento permanente de su color, no se gastan.","Los nobles llegan solos y son gratis: en cuanto cumples sus requisitos, se van contigo (solo uno por turno).","El oro solo se consigue reservando cartas.","Si en una pila no quedan cuatro fichas, no puedes coger dos del mismo color."],"officialLink":{"label":"Web oficial (Space Cowboys)","url":"https://www.spacecowboys.fr/"}}'::jsonb, 148228, null, 0, null, null, 'splendor gemas cartas de descuento y carrera a 15'),
  ('king-of-tokyo', 'King of Tokyo', '👹', 'Monstruos, dados y una ciudad que aguanta lo que puede', null, '{"primary":"#ca4426"}'::jsonb, 2, 6, 'Puntos de victoria', 'PV', 'explicit', 'highest', 20, 13, '{"slug":"king-of-tokyo","name":"King of Tokyo","icon":"👹","tagline":"Monstruos, dados y una ciudad que aguanta lo que puede","theme":{"primary":"#ca4426"},"minPlayers":2,"maxPlayers":6,"playTime":{"min":30,"max":30},"difficulty":"easy","scoreLabel":"Puntos de victoria","scoreLabelShort":"PV","totalMode":"explicit","winnerRule":"highest","targetScore":20,"fields":[{"key":"victory_points","label":"Puntos de victoria","short":"PV","icon":"⭐","type":"number","points":1,"isTotal":true,"min":0,"max":30,"showInSummary":true,"hint":"Se gana con 20, o siendo el último monstruo en pie"},{"key":"health","label":"Vida al acabar","short":"Vida","icon":"❤️","type":"counter","group":"Registro","min":0,"max":12,"showInSummary":true,"hint":"0 significa que quedó eliminado"},{"key":"energy","label":"Energía sin gastar","short":"Energía","icon":"⚡","type":"counter","group":"Registro","min":0,"max":40},{"key":"survived","label":"Sobrevivió hasta el final","short":"Vivo","icon":"🛡️","type":"toggle","group":"Registro"}],"rules":{"players":"2–6 jugadores","duration":"30 min","setup":["Cada jugador elige un monstruo y coge su tablero de vida y puntos: empieza con 10 de vida y 0 puntos.","Coloca el tablero de Tokio en el centro (con 5 o 6 jugadores se usa también la Bahía).","Baraja las cartas de poder y pon tres boca arriba.","Deja los seis dados negros al alcance de todos.","Al principio Tokio está vacío."],"turn":[{"name":"1. Tirar los dados","detail":"Tiras los seis dados y puedes relanzar los que quieras hasta dos veces más."},{"name":"2. Resolver","detail":"Tres iguales de un número dan esos puntos (y uno más por cada dado extra); los rayos dan energía, los corazones curan y las garras hacen daño."},{"name":"3. Comprar poderes","detail":"Con la energía puedes comprar cartas de la oferta, o pagar 2 para renovar las tres cartas visibles."}],"scoring":[{"what":"Tres unos / doses / treses","points":"1 / 2 / 3 puntos"},{"what":"Cada dado igual de más","points":"+1 punto"},{"what":"Entrar en Tokio","points":"+1 punto"},{"what":"Empezar tu turno en Tokio","points":"+2 puntos"},{"what":"Cartas de poder","points":"Lo que indiquen"},{"what":"Meta de la partida","points":"20 puntos"}],"endCondition":"Gana quien llegue a 20 puntos de victoria o el último monstruo que quede con vida. Un monstruo con 0 de vida queda eliminado y, si estaba en Tokio, lo deja libre.","reminders":["Estando en Tokio no puedes curarte con los corazones.","El monstruo de Tokio hace daño a todos los de fuera; los de fuera solo se lo hacen al de Tokio.","Cuando te hacen daño en Tokio puedes ceder el sitio, y entonces entra quien te atacó.","Si Tokio está vacío al final de un ataque, el siguiente monstruo que saque garras entra obligatoriamente.","La vida nunca sube por encima de 10, salvo que una carta diga lo contrario."],"officialLink":{"label":"Web oficial (IELLO)","url":"https://www.iello.fr/"}}}'::jsonb, null, 30, 30, 'easy', '{"players":"2–6 jugadores","duration":"30 min","setup":["Cada jugador elige un monstruo y coge su tablero de vida y puntos: empieza con 10 de vida y 0 puntos.","Coloca el tablero de Tokio en el centro (con 5 o 6 jugadores se usa también la Bahía).","Baraja las cartas de poder y pon tres boca arriba.","Deja los seis dados negros al alcance de todos.","Al principio Tokio está vacío."],"turn":[{"name":"1. Tirar los dados","detail":"Tiras los seis dados y puedes relanzar los que quieras hasta dos veces más."},{"name":"2. Resolver","detail":"Tres iguales de un número dan esos puntos (y uno más por cada dado extra); los rayos dan energía, los corazones curan y las garras hacen daño."},{"name":"3. Comprar poderes","detail":"Con la energía puedes comprar cartas de la oferta, o pagar 2 para renovar las tres cartas visibles."}],"scoring":[{"what":"Tres unos / doses / treses","points":"1 / 2 / 3 puntos"},{"what":"Cada dado igual de más","points":"+1 punto"},{"what":"Entrar en Tokio","points":"+1 punto"},{"what":"Empezar tu turno en Tokio","points":"+2 puntos"},{"what":"Cartas de poder","points":"Lo que indiquen"},{"what":"Meta de la partida","points":"20 puntos"}],"endCondition":"Gana quien llegue a 20 puntos de victoria o el último monstruo que quede con vida. Un monstruo con 0 de vida queda eliminado y, si estaba en Tokio, lo deja libre.","reminders":["Estando en Tokio no puedes curarte con los corazones.","El monstruo de Tokio hace daño a todos los de fuera; los de fuera solo se lo hacen al de Tokio.","Cuando te hacen daño en Tokio puedes ceder el sitio, y entonces entra quien te atacó.","Si Tokio está vacío al final de un ataque, el siguiente monstruo que saque garras entra obligatoriamente.","La vida nunca sube por encima de 10, salvo que una carta diga lo contrario."],"officialLink":{"label":"Web oficial (IELLO)","url":"https://www.iello.fr/"}}'::jsonb, 70323, null, 0, null, null, 'king of tokyo monstruos dados y una ciudad que aguanta lo que puede'),
  ('dixit', 'Dixit', '🐰', 'Una frase, seis ilustraciones y mucha mala idea', null, '{"primary":"#6a4c93"}'::jsonb, 3, 6, 'Puntos', 'Pts', 'explicit', 'highest', 30, 14, '{"slug":"dixit","name":"Dixit","icon":"🐰","tagline":"Una frase, seis ilustraciones y mucha mala idea","theme":{"primary":"#6a4c93"},"minPlayers":3,"maxPlayers":6,"playTime":{"min":30,"max":30},"difficulty":"easy","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","targetScore":30,"fields":[{"key":"points","label":"Puntos finales","short":"Puntos","icon":"🐰","type":"number","points":1,"isTotal":true,"min":0,"showInSummary":true,"hint":"La casilla donde acabó tu conejo"},{"key":"rounds_as_storyteller","label":"Rondas como narrador","short":"Narró","icon":"🗣️","type":"counter","group":"Registro","min":0,"max":30},{"key":"perfect_clues","label":"Pistas redondas","short":"Redondas","icon":"🎯","type":"counter","group":"Registro","min":0,"max":30,"hint":"Cuando te votaron algunos pero no todos: 3 puntos"}],"rules":{"players":"3–6 jugadores","duration":"30 min","setup":["Cada jugador coge un conejo de un color y lo pone en la casilla de salida del marcador.","Reparte seis cartas a cada jugador; se juegan en secreto.","Cada jugador coge las fichas de voto numeradas del 1 al número de jugadores.","Deja el mazo a mano para reponer cartas cada ronda.","Empieza quien tenga la imaginación más despierta, o sortead."],"turn":[{"name":"1. El narrador da la pista","detail":"Elige una carta de su mano sin enseñarla y dice una frase, una palabra, un sonido o un gesto que la describa."},{"name":"2. Los demás aportan","detail":"Cada jugador elige de su mano la carta que mejor pegue con esa pista y se la pasa al narrador, que las mezcla y las pone boca arriba."},{"name":"3. Votación","detail":"Todos menos el narrador votan en secreto cuál creen que es la suya. Después se desvela y se reparten los puntos."}],"scoring":[{"what":"Aciertan todos o no acierta nadie","points":"Narrador 0