  ('everdell', 'Everdell', '🌰', 'Bichos, ciudad de quince cartas y cuatro estaciones', null, '{"primary":"#4a7c59"}'::jsonb, 1, 4, 'Puntos', 'Pts', 'computed', 'highest', null, 21, '{"slug":"everdell","name":"Everdell","icon":"🌰","tagline":"Bichos, ciudad de quince cartas y cuatro estaciones","theme":{"primary":"#4a7c59"},"minPlayers":1,"maxPlayers":4,"playTime":{"min":40,"max":80},"difficulty":"hard","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"computed","winnerRule":"highest","fields":[{"key":"cards","label":"Cartas de la ciudad","short":"Ciudad","icon":"🏘️","type":"number","points":1,"min":0,"showInSummary":true,"hint":"Los puntos impresos en las quince cartas"},{"key":"prosperity","label":"Prosperidad y bonos de cartas","short":"Prosperidad","icon":"✨","type":"number","points":1,"min":0,"showInSummary":true},{"key":"events","label":"Eventos conseguidos","short":"Eventos","icon":"🎪","type":"number","points":1,"min":0,"showInSummary":true},{"key":"journey","label":"Viaje","short":"Viaje","icon":"🧭","type":"number","points":1,"min":0,"showInSummary":true},{"key":"tokens","label":"Fichas de punto","short":"Fichas","icon":"🔶","type":"number","points":1,"min":0,"hint":"Las que se acumulan sobre cartas como el Teatro o la Escuela"},{"key":"workers_left","label":"Obreros sin colocar","short":"Obreros","icon":"🐿️","type":"counter","group":"Registro","min":0,"max":6,"hint":"No suma: se guarda como estadística"}],"rules":{"players":"1–4 jugadores","duration":"40–80 min","setup":["Monta el árbol y coloca las cartas de la pradera: ocho boca arriba.","Pon los cuatro eventos básicos y sortea cuatro especiales.","Cada jugador coge sus obreros y empieza con dos, más 5 cartas en la mano y 1 ramita.","Coloca los recursos de la reserva al alcance de todos.","Todos empezáis en la estación Primavera."],"turn":[{"name":"Opción A — Colocar un obrero","detail":"Pon un obrero en un espacio libre del bosque, de la pradera o de una carta de destino y coge lo que ofrezca."},{"