  ('forbidden-island', 'Forbidden Island', '🗺️', 'La isla se hunde bajo vuestros pies: coged los tesoros y volad', null, '{"primary":"#427f1a"}'::jsonb, 2, 4, 'Resultado', 'Res.', 'computed', 'highest', null, 157, '{"slug":"forbidden-island","name":"Forbidden Island","icon":"🗺️","tagline":"La isla se hunde bajo vuestros pies: coged los tesoros y volad","theme":{"primary":"#427f1a"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":30,"max":30},"difficulty":"easy","scoreLabel":"Resultado","scoreLabelShort":"Res.","totalMode":"computed","winnerRule":"highest","fields":[{"key":"won","label":"Partida ganada","short":"Ganada","icon":"🤝","type":"toggle","points":1,"showInSummary":true,"hint":"Marcadlo todos: en cooperativo se gana en equipo"},{"key":"team_score","label":"Puntuación del equipo","short":"Equipo","icon":"🧮","type":"number","showInSummary":true,"hint":"Si el juego puntúa la victoria. Es informativa: no decide quién gana"}],"rules":{"players":"2–4 jugadores","duration":"30 min","setup":["Montad la isla con las 24 losetas en forma de rombo, todas por el lado seco.","Repartid roles y dos cartas de tesoro a cada uno; si sale «Sube las aguas», descártala y roba otra.","Colocad cada peón en la loseta de su color y los cuatro tesoros junto al tablero.","Ajustad el marcador de agua a la dificultad elegida (novato a leyenda).","Inundad seis losetas: voltéalas al lado azul."],"turn":[{"name":"1. Hasta tres acciones","detail":"Mover, drenar una loseta inundada adyacente, dar una carta de tesoro o reclamar un tesoro entregando 4 cartas iguales en su isla."},{"name":"2. Robar dos cartas de tesoro","detail":"Si sale «Sube las aguas», el marcador de agua sube y las inundaciones descartadas vuelven encima del mazo."},{"name":"3. Inundar","detail":"Voltea tantas cartas de inundación como marque el nivel del agua; una loseta ya inundada que vuelve a salir se hunde para siempre."}],"endCondition":"Ganáis si recogéis los cuatro tesoros, llegáis todos al Helipuerto de los Locos y jugáis «Despega». Perdéis si se hunde una isla de tesoro sin haberlo recogido, si se hunde el helipuerto, si alguien se ahoga o si el agua llega a la calavera.","reminders":["Reclamar un tesoro cuesta 4 cartas de ese tesoro y estar en una de sus dos islas.","Se puede drenar cualquier loseta inundada adyacente (u ocupada), no solo la propia.","Las cartas de helicóptero y saco de arena se juegan en cualquier momento, incluso en el turno de otro.","Si tu peón está en una loseta que se hunde, debes nadar a una adyacente en el acto o pierdes."],"officialLink":{"label":"Web oficial (Gamewright)","url":"https://gamewright.com/"}}}'::jsonb, 'coop', 30, 30, 'easy', '{"players":"2–4 jugadores","duration":"30 min","setup":["Montad la isla con las 24 losetas en forma de rombo, todas por el lado seco.","Repartid roles y dos cartas de tesoro a cada uno; si sale «Sube las aguas», descártala y roba otra.","Colocad cada peón en la loseta de su color y los cuatro tesoros junto al tablero.","Ajustad el marcador de agua a la dificultad elegida (novato a leyenda).","Inundad seis losetas: voltéalas al lado azul."],"turn":[{"name":"1. Hasta tres acciones","detail":"Mover, drenar una loseta inundada adyacente, dar una carta de tesoro o reclamar un tesoro entregando 4 cartas iguales en su isla."},{"name":"2. Robar dos cartas de tesoro","detail":"Si sale «Sube las aguas», el marcador de agua sube y las inundaciones descartadas vuelven encima del mazo."},{"name":"3. Inundar","detail":"Voltea tantas cartas de inundación como marque el nivel del agua; una loseta ya inundada que vuelve a salir se hunde para siempre."}],"endCondition":"Ganáis si recogéis los cuatro tesoros, llegáis todos al Helipuerto de los Locos y jugáis «Despega». Perdéis si se hunde una isla de tesoro sin haberlo recogido, si se hunde el helipuerto, si alguien se ahoga o si el agua llega a la calavera.","reminders":["Reclamar un tesoro cuesta 4 cartas de ese tesoro y estar en una de sus dos islas.","Se puede drenar cualquier loseta inundada adyacente (u ocupada), no solo la propia.","Las cartas de helicóptero y saco de arena se juegan en cualquier momento, incluso en el turno de otro.","Si tu peón está en una loseta que se hunde, debes nadar a una adyacente en el acto o pierdes."],"officialLink":{"label":"Web oficial (Gamewright)","url":"https://gamewright.com/"}}'::jsonb, 65244, null, 0, null, null, 'forbidden island la isla se hunde bajo vuestros pies coged los tesoros y volad'),
  ('forbidden-desert', 'Forbidden Desert', '🌵', 'Sed, tormenta de arena y una nave que hay que montar', null, '{"primary":"#427f1a"}'::jsonb, 2, 5, 'Resultado', 'Res.', 'computed', 'highest', null, 158, '{"slug":"forbidden-desert","name":"Forbidden Desert","icon":"🌵","tagline":"Sed, tormenta de arena y una nave que hay que montar","theme":{"primary":"#427f1a"},"minPlayers":2,"maxPlayers":5,"playTime":{"min":45,"max":45},"difficulty":"easy","scoreLabel":"Resultado","scoreLabelShort":"Res.","totalMode":"computed","winnerRule":"highest","fields":[{"key":"won","label":"Partida ganada","short":"Ganada","icon":"🤝","type":"toggle","points":1,"showInSummary":true,"hint":"Marcadlo todos: en cooperativo se gana en equipo"},{"key":"team_score","label":"Puntuación del equipo","short":"Equipo","icon":"🧮","type":"number","showInSummary":true,"hint":"Si el juego puntúa la victoria. Es informativa: no decide quién gana"}],"rules":{"players":"2–5 jugadores","duration":"45 min","setup":["Formad la cuadrícula de 5×5 con las losetas boca abajo y un hueco central para la tormenta.","Repartid roles; cada peón empieza en el hueco de la tormenta.","Poned dos fichas de arena sobre las losetas que marca el reglamento.","Dad a cada jugador su reserva de agua y ajustad el medidor de tormenta a la dificultad."],"turn":[{"name":"1. Hasta cuatro acciones","detail":"Mover, quitar arena de una loseta adyacente, excavar (voltear la loseta donde estás si no tiene arena) o dar agua."},{"name":"2. Robar cartas de tormenta","detail":"Tantas como marque el medidor: mueven la tormenta y apilan arena; «El sol pega fuerte» hace que todos beban salvo bajo túnel."}],"endCondition":"Ganáis si montáis las cuatro partes de la nave y despegáis todos desde el pozo de aterrizaje. Perdéis si alguien se queda sin agua, si la arena se acaba (sepultura) o si la tormenta llega al final del medidor.","reminders":["Cada parte de la nave se localiza cruzando las pistas de dos losetas de pozo (fila y columna).","No puedes c