  ('clank', 'Clank!', '🐉', 'Roba en la cueva del dragón y sal antes de hacer demasiado ruido', null, '{"primary":"#1a757f"}'::jsonb, 2, 4, 'Puntos', 'Pts', 'explicit', 'highest', null, 238, '{"slug":"clank","name":"Clank!","icon":"🐉","tagline":"Roba en la cueva del dragón y sal antes de hacer demasiado ruido","theme":{"primary":"#1a757f"},"minPlayers":2,"maxPlayers":4,"playTime":{"min":30,"max":60},"difficulty":"medium","scoreLabel":"Puntos","scoreLabelShort":"Pts","totalMode":"explicit","winnerRule":"highest","fields":[{"key":"points","label":"Puntos finales","short":"Puntos","icon":"🏆","type":"number","isTotal":true,"showInSummary":true,"hint":"Lo que sume la hoja de puntuación del juego"}],"rules":{"players":"2–4 jugadores","duration":"30–60 min","setup":["Montad el tablero de la mazmorra y coloca el dragón en su marca de furia inicial.","Cada jugador coge su mazo inicial de 10 cartas y sus 30 cubos de ruido (clank) del color propio.","Formad la reserva del Dungeon Row con seis cartas del mazo de mazmorra.","Poned los artefactos, monstruos y mercado en sus sitios."],"turn":[{"name":"1. Jugar la mano","detail":"Juegas tus cinco cartas y sumas sus habilidades, espadas y botas."},{"name":"2. Comprar y moverte","detail":"Adquieres cartas del Dungeon Row, luchas contra monstruos y te desplazas por las salas."},{"name":"3. Ruido","detail":"Ciertas cartas y pasillos te hacen meter cubos de clank en la bolsa: cuanto más ruido, más peligro."}],"scoring":[{"what":"Artefacto que sacas de la mazmorra","points":"Puntos según su profundidad"},{"what":"Cartas, gemas, monedas y bonos","points":"Puntos de victoria"}],"endCondition":"Debes coger al menos un artefacto y subir a la superficie. Cuando alguien escapa (o cae), empieza la cuenta atrás del dragón; los que no salgan a tiempo y mueran no puntúan. Gana quien más puntos saque vivo.","reminders":["Solo puedes escapar por la superficie si llevas un artefacto; sin él no puntúas nada.","Cada ataque del dragón saca cubos de la bolsa: si salen los tuyos, recibes daño.","La profundidad manda: los artefactos más hondos valen más pero cuesta más volver.","Al desmayarte (10 de daño) dejas de jugar; si estás en zona profunda, mueres y pierdes lo llevado."],"officialLink":{"label":"Web oficial (Renegade Game Studios)","url":"https://renegadegamestudios.com/"}}}'::jsonb, 'points', 30, 60, 'medium', '{"players":"2–4 jugadores","duration":"30–60 min","setup":["Montad el tablero de la mazmorra y coloca el dragón en su marca de furia inicial.","Cada jugador coge su mazo inicial de 10 cartas y sus 30 cubos de ruido (clank) del color propio.","Formad la reserva del Dungeon Row con seis cartas del mazo de mazmorra.","Poned los artefactos, monstruos y mercado en sus sitios."],"turn":[{"name":"1. Jugar la mano","detail":"Juegas tus cinco cartas y sumas sus habilidades, espadas y botas."},{"name":"2. Comprar y moverte","detail":"Adquieres cartas del Dungeon Row, luchas contra monstruos y te desplazas por las salas."},{"name":"3. Ruido","detail":"Ciertas cartas y pasillos te hacen meter cubos de clank en la bolsa: cuanto más ruido, más peligro."}],"scoring":[{"what":"Artefacto que sacas de la mazmorra","points":"Puntos según su profundidad"},{"what":"Cartas, gemas, monedas y bonos","points":"Puntos de victoria"}],"endCondition":"Debes coger al menos un artefacto y subir a la superficie. Cuando alguien escapa (o cae), empieza la cuenta atrás del dragón; los que no salgan a tiempo y mueran no puntúan. Gana quien más puntos saque vivo.","reminders":["Solo puedes escapar por la superficie si llevas un artefacto; sin él no puntúas nada.","Cada ataque del dragón saca cubos de la bolsa: si salen los tuyos, recibes daño.","La profundidad manda: los artefactos más hondos valen más pero cuesta más volver.","Al desmayarte (10 de daño) dejas de jugar; si estás en zona profunda, mueres y pierdes lo llevado."],"officialLink":{"label":"Web oficial (Renegade Game Studios)","url":"https://renegadegamestudios.com/"}}'::jsonb, 