  ('heat-pedal-to-the-metal', 'Heat: Pedal to the Metal', '🏎️', 'Carreras con marchas y calor: pasarse de vueltas se paga', null, '{"primary":"#427f1a"}'::jsonb, 1, 6, 'Victoria', 'Vic.', 'computed', 'highest', null, 242, '{"slug":"heat-pedal-to-the-metal","name":"Heat: Pedal to the Metal","icon":"🏎️","tagline":"Carreras con marchas y calor: pasarse de vueltas se paga","theme":{"primary":"#427f1a"},"minPlayers":1,"maxPlayers":6,"playTime":{"min":30,"max":60},"difficulty":"medium","scoreLabel":"Victoria","scoreLabelShort":"Vic.","totalMode":"computed","winnerRule":"highest","fields":[{"key":"won","label":"Ha ganado","short":"Gana","icon":"👑","type":"toggle","points":1,"uniquePerMatch":true,"showInSummary":true}],"rules":{"players":"1–6 jugadores","duration":"30–60 min","setup":["Elegid un circuito y colocad los coches en la parrilla según el sorteo.","Cada piloto coge su mazo idéntico de cartas de velocidad, sus cartas de calor y su tablero de marchas.","Barajad tu mazo y roba tu mano inicial de siete cartas; el motor arranca en 1ª."],"turn":[{"name":"1. Cambiar de marcha","detail":"Subes o bajas una marcha (o más pagando calor); la marcha fija cuántas cartas juegas."},{"name":"2. Jugar velocidad","detail":"Juegas cartas de tu mano; su suma es lo que avanzas esta vuelta."},{"name":"3. Curvas y calor","detail":"Si pasas una curva por encima de su límite, pagas calor por cada exceso; sin calor, derrapas."}],"scoring":[{"what":"Orden de llegada","points":"Posición en la carrera"}],"endCondition":"Gana quien cruce primero la meta tras completar las vueltas pactadas; en campeonato se suman puntos por posición a lo largo de varias carreras.","reminders":["La marcha limita cuántas cartas juegas: más marcha, más velocidad, pero menos control en las curvas.","Pasarte del límite de una curva cuesta una carta de calor por cada punto de exceso; sin calor en la reserva, giras (spinout).","El rebufo te deja avanzar dos casillas gratis si acabas justo detrás de otro coche.","El calor entra en tu mazo como carta muerta: gestionar el motor es medio juego."],"officialLink":{"label":"Web oficial (Days of Wonder)","url":"https://www.daysofwonder.com/"}}}'::jsonb, 'win', 30, 60, 'medium', '{"players":"1–6 jugadores","duration":"30–60 min","setup":["Elegid un circuito y colocad los coches en la parrilla según el sorteo.","Cada piloto coge su mazo idéntico de cartas de velocidad, sus cartas de calor y su tablero de marchas.","Barajad tu mazo y roba tu mano inicial de siete cartas; el motor arranca en 1ª."],"turn":[{"name":"1. Cambiar de marcha","detail":"Subes o bajas una marcha (o más pagando calor); la marcha fija cuántas cartas juegas."},{"name":"2. Jugar velocidad","detail":"Juegas cartas de tu mano; su suma es lo que avanzas esta vuelta."},{"name":"3. Curvas y calor","detail":"Si pasas una curva por encima de su límite, pagas calor por cada exceso; sin calor, derrapas."}],"scoring":[{"what":"Orden de llegada","points":"Posición en la carrera"}],"endCondition":"Gana quien cruce primero la meta tras completar las vueltas pactadas; en campeonato se suman puntos por posición a lo largo de varias carreras.","reminders":["La marcha limita cuántas cartas juegas: más marcha, más velocidad, pero menos control en las curvas.","Pasarte del límite de una curva cuesta una carta de calor por cada punto de exceso; sin calor en la reserva, giras (spinout).","El rebufo te deja avanzar dos casillas gratis si acabas justo detrás de otro coche.","El calor entra en tu mazo como carta muerta: gestionar el motor es medio juego."],"officialLink":{"label":"Web oficial (Days of Wonder)","url":"https://www.daysofwonder.com/"}}'::jsonb, 366013, null, 0, null, null, 'heat pedal to the metal carreras con marchas y calor pasarse de vueltas se paga'),
