  ('chess', 'Ajedrez', '♟️', 'El juego del que salen todos los demás', null, '{"primary":"#0f5499"}'::jsonb, 2, 2, 'Victoria', 'Vic.', 'computed', 'highest', null, 382, '{"slug":"chess","name":"Ajedrez","icon":"♟️","tagline":"El juego del que salen todos los demás","theme":{"primary":"#0f5499"},"minPlayers":2,"maxPlayers":2,"playTime":{"min":30,"max":60},"difficulty":"hard","scoreLabel":"Victoria","scoreLabelShort":"Vic.","totalMode":"computed","winnerRule":"highest","fields":[{"key":"won","label":"Ha ganado","short":"Gana","icon":"👑","type":"toggle","points":1,"uniquePerMatch":true,"showInSummary":true}],"rules":{"players":"2 jugadores","duration":"30–60 min","setup":["Colocad el tablero con una casilla blanca en la esquina derecha de cada jugador.","Fila de atrás: torre, caballo, alfil, dama, rey, alfil, caballo, torre; la dama va en su propio color.","Los ocho peones, delante. Empiezan las blancas."],"turn":[{"name":"Mover una pieza","detail":"Cada bando mueve una pieza por turno según su patrón; capturar es ocupar la casilla del rival."}],"endCondition":"Ganas dando jaque mate: el rey rival está amenazado y no puede evitarlo. Hay tablas por rey ahogado, material insuficiente, triple repetición, regla de los 50 movimientos o acuerdo mutuo.","reminders":["No puedes hacer una jugada que deje (o mantenga) a tu propio rey en jaque.","El enroque mueve rey y torre a la vez, si ninguno se ha movido y no hay jaque por medio.","La captura «al paso» solo puede hacerse justo después de que un peón avance dos casillas.","Un peón que llega a la última fila corona, normalmente a dama."],"officialLink":{"label":"Leyes del ajedrez (FIDE)","url":"https://www.fide.com/"}}}'::jsonb, 'win', 30, 60, 'hard', '{"players":"2 jugadores","duration":"30–60 min","setup":["Colocad el tablero con una casilla blanca en la esquina derecha de cada jugador.","Fila de atrás: torre, caballo, alfil, dama, rey, alfil, caballo, torre; la dama va en su propio color.","Los ocho peones, delante. Empiezan las blancas."],"turn":[{"name":"Mover una pieza","detail":"Cada bando mueve una pieza por turno según su patrón; capturar es ocupar la casilla del rival."}],"endCondition":"Ganas dando jaque mate: el rey rival está amenazado y no puede evitarlo. Hay tablas por rey ahogado, material insuficiente, triple repetición, regla de los 50 movimientos o acuerdo mutuo.","reminders":["No puedes hacer una jugada que deje (o mantenga) a tu propio rey en jaque.","El enroque mueve rey y torre a la vez, si ninguno se ha movido y no hay jaque por medio.","La captura «al paso» solo puede hacerse justo después de que un peón avance dos casillas.","Un peón que llega a la última fila corona, normalmente a dama."],"officialLink":{"label":"Leyes del ajedrez (FIDE)","url":"https://www.fide.com/"}}'::jsonb, 171, null, 0, null, null, 'ajedrez el juego del que salen todos los demas'),
  ('go', 'Go', '⚫', 'Reglas de una página y una vida entera para aprenderlo', null, '{"primary":"#2847c3"}'::jsonb, 2, 2, 'Victoria', 'Vic.', 'computed', 'highest', null, 383, '{"slug":"go","name":"Go","icon":"⚫","tagline":"Reglas de una página y una vida entera para aprenderlo","theme":{"primary":"#2847c3"},"minPlayers":2,"maxPlayers":2,"playTime":{"min":30,"max":180},"difficulty":"hard","scoreLabel":"Victoria","scoreLabelShort":"Vic.","totalMode":"computed","winnerRule":"highest","fields":[{"key":"won","label":"Ha ganado","short":"Gana","icon":"👑","type":"toggle","points":1,"uniquePerMatch":true,"showInSummary":true}],"rules":{"players":"2 jugadores","duration":"30–180 min","setup":["Tablero de 19×19 vacío (9×9 o 13×13 para aprender).","Un jugador coge las piedras negras y el otro las blancas; empiezan las negras.","Acordad el komi: puntos de compensación para las blancas por jugar segundas (unos 6,5)."],"turn":[{"name":"Poner o pasar","detail":"En tu turno colocas una piedra en una intersección vacía, o pasas."},{"name":"Capturar","detail":"Un grupo enemigo sin ninguna libertad (intersección vacía adyacente) se retira del tablero."}],"endCondition":"La partida acaba con dos pasos seguidos. Se cuenta el territorio rodeado más las piezas capturadas (más el komi para blancas). Gana quien más sume.","reminders":["Prohibido el suicidio: no puedes poner una piedra sin libertades, salvo que con ello captures.","Regla del ko: no puedes recrear de inmediato la posición anterior del tablero.","Un grupo con dos «ojos» verdaderos es inmatable: ahí está la vida y la muerte del go.","El komi compensa la ventaja de salir primero: sin él, las negras ganan casi siempre."],"officialLink":{"label":"Reglas del Go (British Go Association)","url":"https://www.britgo.org/"}}}'::jsonb, 'win', 30, 180, 'hard', '{"players":"2 jugadores","duration":"30–180 min","setup":["Tablero de 19×19 vacío (9×9 o 13×13 para aprender).","Un jugador coge las piedras negras y el otro las blancas; empiezan